// server/sim/content/hextech.js — 海克斯 (Hextech) content (DESIGN §29).
//
// The 38 player hexes live in data/hextech.json (generated by tools/build-hextech.mjs from tools/hextech/roster.mjs);
// this module owns what a picked hex DOES, on both sides of the same shared code (the match server and the browser's
// battle sim import it from /sim/).
//
// Prep side — registerMeta(registry) registers one `hex:<id>` handler per player hex:
//   effect.onPick        runs once, when the player picks the hex (dispatch.runKey from server/match/hextech.js)
//   effect.onRoundStart  runs at the start of every round's prep phase the player is alive for; `everyRounds: N`
//                        throttles it with a per-hex counter (N = 3 → rounds 1, 4, 7 …), so no new player state
// Every key maps to a ctx primitive: funds / freeRefresh / item / chess / layers / allActiveLayers. `effect.onPick.lp`
// is applied by server/match/hextech.js (the ctx has no LP mutator, and LP is match state, not sim state).
//
// Battle side — install(battle) reads each player's battle EffectRefs (key 'hex:<id>', params = the effect record) and
// applies the operator passives at battle start through the shared support helpers (directMods / passiveBuff), i.e. the
// same additive stacking every bond, band, equipment and 机变 bonus uses. (不灭壁垒's "first leak is free" — the
// settlement half lives in server/match/match/settle.js — lost its last card in §29.22; that code remains.)
//
// Content is optional: a build without data/hextech.json registers nothing and install() finds no refs.

import { gameData, directMods, passiveBuff, unitBonds, bondActive, bondLayers, isMember, isOp, fxOn } from './support/index.js';
import { fissionBondIds as sharedFissionBondIds, fissionCap } from '../../../shared/hextech.js';
import { elem, hurt, areaAlliesInTiles, spawnChildren, isHitCount, abOf } from './enemies/helpers.js';
import { hexHooks } from './hexcards/hooks.js';

/**
 * Which lane a script-spawned enemy should take when the field offers several.
 *
 * 业主 2026-10-20「联防时敌方协议悬赏令的怪路径有问题」：联防场把**每一条**漏怪波次的路线都带进来，`routes[0]` 常常是
 * 飞行道（FLY）。一条路线就是一串折线，引擎**不**沿着地形寻路，所以把地面怪放上飞行道＝直接穿过悬崖和岩石。
 * 这里按 spawn 自己的 motion 挑：飞行怪优先挑 FLY 道，地面怪挑非 FLY 道；挑不到就退回 0（没有更好的选择）。
 * @param {any} battle
 * @param {string} enemyKey
 * @returns {number} route index
 */
/**
 * 这个单位在引擎里**永远不能被阻挡**吗（`battle/blocking.js _checkBlock` 的那四个 flag）。
 *
 * 隐腻/隐匿 这类「被阻挡才解除」的效果要问这个问题：解不掉 = 一整场都点不到。
 * @param {any} unit
 * @returns {boolean}
 */
function cannotBeBlocked(unit) {
  const f = unit && unit.s && unit.s.flags;
  if (!f) return false;
  return !!(f.unblockable || f.levitate || f.fear || f.sleep);
}

function routeIndexForMotion(battle, enemyKey) {
  const routes = Array.isArray(battle && battle.routes) ? battle.routes : [];
  if (!routes.length) return 0;
  let def = null;
  try { def = battle.data && typeof battle.data.getEnemy === 'function' ? battle.data.getEnemy(enemyKey) : null; } catch { def = null; }
  const flies = !!def && def.motion === 'FLY';
  const isFly = (r) => !!r && r.motion === 'FLY';
  const wantFly = flies;
  const hit = routes.findIndex((r) => isFly(r) === wantFly);
  return hit >= 0 ? hit : 0;
}
import { installDrill } from './hexcards/drill.js';
import { installArmor } from './hexcards/armor.js';
import { installShieldwall } from './hexcards/shieldwall.js';
import { installWarmachine } from './hexcards/warmachine.js';
import { installHumanRite } from './hexcards/humanrite.js';
import { installRangeDist } from './hexcards/rangedist.js';
import { installMinefield } from './hexcards/minefield.js';
import { installBreaker } from './hexcards/breaker.js';
import { installNeurotoxin } from './hexcards/neurotoxin.js';
import { installRicochet } from './hexcards/ricochet.js';
import { installLogos } from './hexcards/logos.js';
import { installOneBody } from './hexcards/onebody.js';
// tenth batch (the owner's list of 2026-10-15): the seven battle scripts of hexcards/batch10.js.
import {
  installBlockwall, installSharePain, installTerraMourn, installDirectiveAtk,
  installDirectiveType, installRabbitHead, installProfResonance,
} from './hexcards/batch10.js';
// thirteenth batch (业主 2026-10-19): the battle halves of 踢踏舞 / 终极刷新 / 不祥契约 / 蛋白粉奶昔 / 重量级打击手.
import {
  installTapdance, installUltrefresh, installOmenpact, installProteinShake, installHeavyHitter,
} from './hexcards/batch14b.js';
// thirteenth batch (业主 2026-10-19): the battle halves of 你摸不到 / 珠光护手 / 物法皆修 / 量子计算 / 冰霜幽灵.
import {
  installUntouchable, installPearlGlove, installPhysArts, installQuantum, installFrostGhost,
} from './hexcards/batch14a.js';
// fourteenth batch (业主 2026-10-19): 残光 / 玻璃大炮 / 身负重担 / 破伞 (batch15a.js) 与 加护 / 万物归虚 / 尸山 /
// 旧日之力 (batch15b.js). Four of them grant their own equipment 残光 / 加护 / 万物归虚 / 尸山, which decides WHO the
// battle half acts on (the `carries` rule 恶魔之契 already uses).
import { installCanlight, installGlassCannon, installHeavyLoad, installUmbrellaBreak } from './hexcards/batch15a.js';
import { installWarding, installVoidReturn, installCorpseHill, installOldPower } from './hexcards/batch15b.js';
import { reviveNow, carries } from './items/battle.js';

/** Player effect-ref key prefix (parallel to `choice:`). */
export const HEX_KEY = 'hex:';

/**
 * 恶魔形态's own equipment 恶魔之契 (`CUSTOM_ITEMS` `chess_item_9_91_e_a` in tools/build-data.mjs, §29.32): the card grants
 * it on pick, and the battle half buffs the operators CARRYING it instead of a random one — the owner's request
 * (「如果像幽魂形态一样给个装备来决定对谁生效就好了」). `itemKeyOf` (content/support) strips the `_a` suffix, which is
 * the key `carries` matches (an own copy or a lent grant).
 */
export const DEMON_PACT_ITEM_KEY = 'chess_item_9_91_e';

const isPos = (v) => typeof v === 'number' && Number.isFinite(v) && v > 0;
const countOf = (v, d = 1) => (Number.isInteger(v) && v > 0 ? v : d);
const pct = (v) => (typeof v === 'number' && Number.isFinite(v) ? v / 100 : 0);
/**
 * Can a bond HOLD layers? bonds.json `noStack` (调和 / 独行 / 绝技 / 协防干员) says no: their effects are plain
 * member-count sentences with no per-layer number, so the game never shows a layer count for them (the result card and
 * the bond strip both drop it — public/js/screens/result.js) and every layer GRANT skips them (the 文火慢炖 band strategy
 * is the one place the rule was already written down, server/sim/content/bands/meta.js).
 *
 * 均衡盟约 (§29.34) reads this: it redistributes the layers the active bonds actually HOLD, so such a bond neither takes
 * a share out of the pool nor receives one. Without the guard a 独行 / 绝技 board (both are trivially active) added two
 * layer-less bonds to the denominator AND handed them a permanent number the player can never see or spend — the card was
 * a straight loss for the boards it looked strongest on (业主 report 2026-10-14: 「不应该均衡绝技和独行这种层数没意义的」).
 * The 调和 +1 count mechanism and 独行's "exactly one" sentence are member-count rules and are untouched by this: it only
 * decides who takes part in a LAYER redistribution.
 */
const bondRecord = (ctx, bondId) => {
  const gd = ctx && ctx.gd;
  if (!gd) return null;
  // the match ctx hands over a GameData (gd.bond(id)); a sim-side ctx or a test stub may carry the raw data object
  // (gd.bonds[id]) — both shapes must resolve, or the guard would silently fail open on a stub
  if (typeof gd.bond === 'function') return gd.bond(bondId);
  return (gd.bonds && gd.bonds[bondId]) || null;
};
const holdsLayers = (ctx, bondId) => {
  const rec = bondRecord(ctx, bondId);
  return !(rec && rec.noStack);
};
/**
 * The round a hook is running in: the dispatched event carries its own `round` (`Match.dispatch(ps, 'onRoundStart',
 * { round })`), and a hook that has none (onHexPick) falls back to the match's current round.
 */
const roundOf = (ctx) => {
  const r = Number(ctx && ctx.event && ctx.event() && ctx.event().round);
  return Number.isFinite(r) && r > 0 ? Math.trunc(r) : ctx.round;
};

/**
 * 不灭壁垒's revive hook priority: last in line, after every deployable-revive mechanic that already exists —
 * 埃芒加德 (`PRIO_RESPAWN` 13), the band revive (12), 阿戈尔 (11) and 不屈 (10) — so a card that revives every
 * operator once is only spent for an operator nothing else could save.
 */
const PRIO_HEX_REVIVE = 9;

/**
 * The roster of data/hextech.json, or null.
 *
 * Read through `gameData()`: on the server that is the process singleton of server/data.js, and in the browser it is the
 * DATA_SHIM_JS stand-in over `getSimData()` — the data the page's loader injected (`/js/battle/runner.js`
 * `SIM_DATA_FILES`). So the file has to be in BOTH lists; it is (2026-10-11 fix).
 *
 * `source` is an optional extra place to look, for a caller that holds a raw data object of its own (a test, a tool, or
 * a Battle whose `data` view happens to carry the roster). It never replaces the global read — only adds a chance to
 * find the file, which is what keeps one missing loader entry from silently disabling every verb card.
 * @param {any} [source] a raw `{ hextech }` object (or a Battle / DataSource exposing one)
 */
function hexData(source = null) {
  const from = (o) => {
    const h = o && typeof o === 'object' ? o.hextech : null;
    return h && typeof h === 'object' ? h : null;
  };
  const direct = from(source);
  if (direct) return direct;
  const viaData = source && typeof source === 'object' && !Array.isArray(source)
    ? from(source.data) || from(source.raw)
    : null;
  if (viaData) return viaData;
  return from(gameData());
}

/** Every player hex id (tests / the coverage assertion). */
export function hexIds() {
  const d = hexData();
  return d && d.playerHexes ? Object.keys(d.playerHexes).sort() : [];
}

/**
 * Spec keys of a player hex whose mechanic acts INSIDE a battle without carrying a `effect.battle` passive (the third
 * batch's conditional passives, DESIGN §29.7). The engine's EffectRef `battle` field only ever mirrored
 * `params.battle`, so a ref whose only battle part is one of these was built with `battle: false` and then dropped by
 * `player/round.js battleInput` — the whole mechanic silently never ran. `install()` reads these:
 *
 *   per owner off the ref (`specOf`) — armorBreak · killGift · skillFlow · devourTarget · indomEmber · bondFission
 *     (its `mul`), northWall · precisionPen, and the fourth batch's holdLine · rangedExtend · lastStand · overdrive ·
 *     fieldHospital · elemAmp;
 *   特质扩散 through the module that installs 特质 (`content/garrisons/battle.js` matches the ref KEY).
 *
 * `server/match/hextech.js addHexRef` asks the predicate below, so a new battle mechanic must be declared here (beside
 * the `install` reader) or its ref never leaves the prep phase.
 */
export const BATTLE_SPEC_KEYS = Object.freeze([
  'armorBreak', 'killGift', 'skillFlow', 'devourTarget', 'indomEmber', 'bondFission', 'northWall', 'precisionPen',
  'traitSpread',
  // fourth batch (2026-10-09)
  'holdLine', 'rangedExtend', 'lastStand', 'overdrive', 'fieldHospital', 'elemAmp',
  // fifth batch (2026-10-11): the four scripts of server/sim/content/hexcards/ — 精锐训练's per-round growth, 反击装甲's
  // riposte, 盾墙's adjacent-重装 split and 战争机器's 联防 aura. Each is dispatched by installHexCards() below.
  'drill', 'armor', 'shieldwall', 'warmachine',
  // fourteenth batch (业主 2026-10-19): the eight scripts of hexcards/batch15a.js + batch15b.js. Ownership-only
  // mechanics, so each key MUST be listed here or the ref never reaches a battle (the card would be silently inert).
  'canlight', 'glasscannon', 'heavyload', 'umbrellabreak', 'warding', 'voidreturn', 'corpsehill', 'oldpower',
  // sixth batch (the owner's list of 2026-10-11): the other six scripts of hexcards/ — 人祭's 炎佑 on a knock-out,
  // 近大远小's distance multiplier, 雷区's mines, 破隐's reveal, 神经毒素's poison and 跳弹's ricochet. 债务 is the only
  // card of the batch with no battle part (its watcher lives in the prep phase: server/match/hextech.js `applyHexExtras`
  // + the `effect:hexdebt` handler registered by registerMeta below).
  'humanRite', 'rangedist', 'minefield', 'breaker', 'neurotoxin', 'ricochet',
  // owner's list of 2026-10-12: 不灭壁垒's per-operator revive (its `battle.maxHpPct` already carries the ref, but the
  // mechanic itself has to be declared beside its `install` reader like every other one).
  'immortalRevive',
  // eighth batch (the same day's second list, §29.23): 恶魔形态's per-second ATK growth and 群蛇形态's battle-start
  // kills (the match writes their counts into the ref's params at battle creation).
  'demonForm', 'serpentKills',
  // tenth batch (the owner's list of 2026-10-12, §29.27): 逻各斯's execution aura and 你我一体's shared pool / focus
  // fire. Both are ownership-only mechanics (no `params.battle`), so each has to be declared here beside its `install`
  // reader or `addHexRef` marks the ref prep-only and the battle never sees the card.
  'logos', 'oneBody',
  // tenth batch (the owner's list of 2026-10-15): 挡挡's block-slot ladder, 不区区's damage share, 泰拉在上's death
  // blast, the two 指令之意 rolls, 兔头's ranking and 职业共鸣's profession count. All ownership-only mechanics (no
  // params.battle passive), so each key MUST be declared here or addHexRef marks the ref prep-only and the battle
  // never sees the card.
  'blockwall', 'sharePain', 'deathBlast', 'directiveAtk', 'directiveType', 'rabbitHead', 'profResonance',
  // eleventh batch (the owner's own list of 2026-10-13, §29.34): 背水一战's ×layerMul, which the sim applies on the
  // `layerGain` hook. The match stamps `lastDitch.active` into the ref at battle start (`onBattleStart.lastDitchArm`) —
  // the sim has no LP — and this key is what keeps the ref in the battle input in the first place.
  'lastDitch',
  // thirteenth batch (业主 2026-10-19): every one of the ten new cards is a pure battle script (no prep half), so each
  // key MUST be declared here or addHexRef marks the ref prep-only and the battle never sees the card.
  'untouchable', 'pearlglove', 'physarts', 'quantum', 'tapdance',
  'ultrefresh', 'omenpact', 'proteinshake', 'frostghost', 'heavyhitter',
]);

/**
 * Whether a battle reads this hex's ref — now or after a later prep-side hook writes its battle part.
 *
 * Three shapes qualify:
 *   * a `params.battle` passive (精锐训练 / 反击装甲 / 不灭壁垒 / 先锋之势, and 孤注一掷's `battleForRounds`);
 *   * one of BATTLE_SPEC_KEYS (the ownership/conditional mechanics above);
 *   * 传承: `applySpec` `bondAtkPct` ACCUMULATES `params.battle.bondAtk` onto this ref on every sale, which `install`
 *     reads at the next battle start — the ref therefore has to be battle-visible BEFORE the first sale.
 */
export function hasBattlePart(params) {
  if (!params || typeof params !== 'object') return false;
  if (params.battle && typeof params.battle === 'object') return true;
  if (BATTLE_SPEC_KEYS.some((k) => params[k] !== undefined && params[k] !== null && params[k] !== false)) return true;
  const sold = params.onSold;
  return !!sold && typeof sold === 'object' && sold.bondAtkPct !== undefined && sold.bondAtkPct !== null;
}

/**
 * Apply one effect spec through the ctx primitives. `{ funds, freeRefresh, item:{tier,count}, chess:{tier,count},
 * layers:{count,bonds}, allActiveLayers, dividend… }` — returns whether anything ran. `chess.tier` may be the token
 * `'level'` (the current 调度中心 level); `item.tier` stays a number. `hex`/`hook` are needed by the spec keys that are
 * per-hex state (rebate's counter, 传承's accumulated atkPct) and by the hook-sensitive halves.
 * @param {any} ctx @param {any} spec @param {any} [hex] the data/hextech.json record @param {string} [hook]
 */
function applySpec(ctx, spec, hex = null, hook = '') {
  if (!spec || typeof spec !== 'object') return false;
  const id = hex && typeof hex.id === 'string' ? hex.id : '';
  let did = false;
  if (isPos(spec.funds)) { ctx.addFunds(spec.funds, 'hex'); did = true; }
  if (isPos(spec.freeRefresh)) { ctx.grantFreeRefresh(spec.freeRefresh); did = true; }
  // The outer guard accepts EITHER form: a count-driven grant (id / pool / tier) or the `ids` list (武器大师, which has
  // no count at all — gating on `count` skipped the whole block and the card granted nothing, silently).
  if (spec.item && (isPos(spec.item.count) || (Array.isArray(spec.item.ids) && spec.item.ids.length))) {
    // Three shapes (the third added by the remake's own equipment, §29.24):
    //   { id: '<itemId>' } — an EXPLICIT record (幽魂): no roll and no pool, the card names the equipment it grants.
    //   { pool: 'pool_equip_normal' } — a choices.json equip pool. `ctx.rollPool` injects `shopLevel: ps.shop.level`, and
    //     the pool's own `maxTier: 'shopLevel'` is what makes 军械库 "不高于调度中心等级". This is the path 凯瑟琳
    //     【定向投放】 uses (bands/meta.js up_shop_add_special_goods → rollItems → ctx.rollPool).
    //   { tier: N } — a fixed numeric tier (后勤整备's Tier-1 item). NOTE: `tier` must stay an integer — rollItemId
    //     branches on `Number.isInteger(tier)` and ignores `maxTier` when it is one, so a `'level'` token here would
    //     silently roll tier 1 (tools/build-hextech.mjs rejects it; use `pool` for the level-scaled roll).
    const shopLevel = typeof ctx.shopLevel === 'function' ? ctx.shopLevel() : 6;
    // A FOURTH shape (the owner's list of 2026-10-15, 武器大师): `ids: ['a', 'b']` grants ONE of EACH named record,
    // in order. The single-`id` form cannot express a card that hands out two DIFFERENT pieces of equipment, and the
    // pool/tier forms roll — neither is what 「给一个天马之盔和一个天马之枪」 means.
    if (Array.isArray(spec.item.ids) && spec.item.ids.length) {
      for (const want of spec.item.ids) {
        if (typeof want === 'string' && want) ctx.grantItem(want, { source: 'hex' });
      }
      did = true;
    } else {
      for (let i = 0; i < countOf(spec.item.count); i++) {
        const gid = typeof spec.item.id === 'string' && spec.item.id
          ? spec.item.id
          : typeof spec.item.pool === 'string' && spec.item.pool
            ? (typeof ctx.rollPool === 'function' ? (ctx.rollPool(spec.item.pool) || {}).id ?? null : null)
            : ctx.rollItem({ tier: Number.isInteger(spec.item.tier) ? spec.item.tier : 1, maxTier: Math.max(Number.isInteger(spec.item.tier) ? spec.item.tier : 1, shopLevel) });
        if (gid) ctx.grantItem(gid, { source: 'hex' });
      }
      did = true;
    }
  }
  // 后勤整备 (2026-10-12 rebalance): a GOLDEN (进阶) equipment grant whose TIER is on a ladder —
  //   { tier: 1 }     — a fixed tier (the pick's 1 阶进阶装备)
  //   { tier: 'next' } — one tier above the last one GRANTED (the every-2-rounds half; x = 上次获得装备阶级)
  // The last granted tier lives in the hex's own counter, so the ladder only ever moves forward on a grant that
  // actually landed: a grant that found no free stock (a golden needs TWO spare copies of its base item — pool.js
  // `need`) leaves the counter alone, and the next scheduled round start retries the SAME tier. Tiers are clamped to
  // 1..6 (the item table's range); an empty counter means 'next' = tier 1.
  if (spec.goldenItem && isPos(spec.goldenItem.count)) {
    const key = `${HEX_KEY}${id}:goldenTier`;
    const last = Math.max(0, Math.trunc(Number(ctx.counter(key)) || 0));
    const want = spec.goldenItem.tier === 'next'
      ? Math.min(6, last + 1)
      : Math.max(1, Math.min(6, Number.isInteger(spec.goldenItem.tier) ? spec.goldenItem.tier : 1));
    for (let i = 0; i < countOf(spec.goldenItem.count); i++) {
      const gid = typeof ctx.rollGoldenItem === 'function' ? ctx.rollGoldenItem({ tier: want }) : null;
      if (!gid) break;
      if (ctx.grantItem(gid, { source: 'hex' })) { ctx.setCounter(key, want); did = true; }
    }
  }
  if (spec.chess && isPos(spec.chess.count)) {
    // `tier: 'level'` = the player's current 调度中心 level, so the grant escalates with the shop (量产线 / 精锐预兆);
    // `same: true` = ONE roll granted `count` times — three identical copies merge immediately (精锐预兆's 同名 3 张)
    const lvl = typeof ctx.shopLevel === 'function' ? Math.max(1, Math.trunc(ctx.shopLevel())) : 1;
    const tier = spec.chess.tier === 'level' ? lvl : Number.isInteger(spec.chess.tier) ? spec.chess.tier : 1;
    const n = countOf(spec.chess.count);
    if (spec.chess.same) {
      const id = ctx.rollChess({ tier, maxTier: tier });
      if (id) for (let i = 0; i < n; i++) ctx.grantChess(id, { source: 'hex' });
    } else {
      for (let i = 0; i < n; i++) {
        const id = ctx.rollChess({ tier, maxTier: tier });
        if (id) ctx.grantChess(id, { source: 'hex' });
      }
    }
    did = true;
  }
  if (spec.layers && isPos(spec.layers.count)) {
    const n = countOf(spec.layers.count);
    const want = countOf(spec.layers.bonds, 1);
    const pool = Array.isArray(ctx.gd.bondIds) ? ctx.gd.bondIds.slice() : [];
    for (let i = 0; i < want && pool.length; i++) {
      const k = Math.min(pool.length - 1, Math.floor(ctx.rng() * pool.length));
      const bondId = pool.splice(k, 1)[0];
      ctx.addLayers(bondId, n, { reason: 'hex' });
    }
    did = true;
  }
  if (isPos(spec.allActiveLayers)) {
    for (const [bondId, st] of Object.entries(ctx.bonds())) {
      if (st && st.active) ctx.addLayers(bondId, spec.allActiveLayers, { reason: 'hex' });
    }
    did = true;
  }
  // ---- second batch (0.3.0 playtest #2) --------------------------------------------------------------
  // 源石红利: accrue what the round spends (onSpend), pay 1 per 5 spent at the next round start (keeping the remainder)
  if (spec.rebateAccrue) {
    const amt = Number(ctx.event()?.amount);
    if (Number.isFinite(amt) && amt > 0) { ctx.incCounter(`${HEX_KEY}${id}:spent`, Math.trunc(amt)); did = true; }
  }
  if (spec.rebatePay && isPos(spec.rebatePay.per) && isPos(spec.rebatePay.gain)) {
    const spent = ctx.counter(`${HEX_KEY}${id}:spent`);
    const n = Math.floor(spent / spec.rebatePay.per) * spec.rebatePay.gain;
    if (n > 0) ctx.addFunds(n, 'hex');
    ctx.setCounter(`${HEX_KEY}${id}:spent`, spent % spec.rebatePay.per);
    did = true;
  }
  // 调度直播: rewrite one shop slot with a random operator of the own board (normal price)
  if (spec.shopSlot && Number.isInteger(spec.shopSlot.index)) {
    const picks = (ctx.board() || []).filter((p) => p && p.kind === 'chess' && typeof p.id === 'string');
    if (picks.length) {
      const pick = picks[Math.min(picks.length - 1, Math.floor(ctx.rng() * picks.length))];
      if (pick && ctx.setShopSlot(spec.shopSlot.index, { kind: 'chess', id: pick.id })) did = true;
    }
  }
  // 传承: every sale adds +N % ATK, permanently, for the operators sharing one of the sold bonds. The per-bond pot
  // lives on the hex's own EffectRef (params.battle.bondAtk), which the battle side reads at battle start.
  if (spec.bondAtkPct && isPos(spec.bondAtkPct)) {
    const piece = ctx.event()?.piece;
    const rec = piece && piece.kind === 'chess' && typeof piece.id === 'string' ? ctx.gd.chess(piece.id) : null;
    const bonds = rec && Array.isArray(rec.bonds) ? rec.bonds.filter((b) => typeof b === 'string') : [];
    const refId = `hex:${id}`;
    const cur = ctx.effect(refId);
    if (bonds.length && cur) {
      const acc = { ...(cur.params && cur.params.battle && cur.params.battle.bondAtk ? cur.params.battle.bondAtk : {}) };
      for (const b of bonds) acc[b] = Math.round(((Number(acc[b]) || 0) + spec.bondAtkPct) * 100) / 100;
      ctx.addEffect({ id: refId, params: { ...(cur.params || {}), battle: { ...(cur.params?.battle || {}), bondAtk: acc } } });
      did = true;
    }
  }
  // 战损回收: funds per **LP actually charged this round**, at settlement (next prep).
  //
  // Owner's call 2026-10-18: the card now pays for the damage taken, not for the leaks. It used to be 1/leak
  // (doubled to 2 when a 协防 had failed and charged LP); the payout is now a flat `perLpLoss` per LP of
  // `ev.lpLoss` — the settlement's own number, cap unchanged. Reading `lpLoss` instead of counting `leaked`
  // is what makes the card follow the real cost: a 联防 leaker is charged only for what got past the helpers,
  // and a protocol level's extra leak LP (settle.js `levelLeak`) is charged on top, so both now count.
  //
  // 过路费 (the enemy hex `payout`) still pays per leak — that is a different card and keeps its own reading.
  if (isPos(spec.perLpLoss)) {
    const charged = Number(ctx.event()?.lpLoss);
    if (Number.isFinite(charged) && charged > 0) {
      const cap = Number.isInteger(spec.cap) && spec.cap > 0 ? spec.cap : Infinity;
      ctx.addPendingFunds(Math.min(cap, Math.trunc(charged) * spec.perLpLoss));
      did = true;
    }
  }
  // 战损回收's old shape (`perLeak` / `perLeakAfterLoss`): kept readable so an already-installed pack that
  // declares it still pays, but the bundled card no longer uses it (see the comment above).
  if (isPos(spec.perLeak)) {
    const ev = ctx.event() || {};
    const leaked = (ev.result?.leaked || []).filter((l) => l && l.counted !== false).length;
    if (leaked > 0) {
      const charged = Number(ev.lpLoss);
      const per = ev.unite != null && Number.isFinite(charged) && charged > 0 && isPos(spec.perLeakAfterLoss)
        ? spec.perLeakAfterLoss
        : spec.perLeak;
      const cap = Number.isInteger(spec.cap) && spec.cap > 0 ? spec.cap : Infinity;
      ctx.addPendingFunds(Math.min(cap, leaked * per));
      did = true;
    }
  }
  // ---- fourth batch (owner's review of 2026-10-09) ---------------------------------------------------
  // 战功簿: funds per `per` knock-outs of the round's own battle, at settlement (next prep). The mirror of 战损回收
  // (perLeak): one pays for what leaked, this one pays for what died.
  if (spec.perKill && isPos(spec.perKill.per) && isPos(spec.perKill.gain)) {
    const killed = Number(ctx.event()?.result?.killed) || 0;
    if (killed > 0) {
      const n = Math.floor(killed / spec.perKill.per) * spec.perKill.gain;
      if (n > 0) {
        const cap = Number.isInteger(spec.perKill.cap) && spec.perKill.cap > 0 ? spec.perKill.cap : Infinity;
        ctx.addPendingFunds(Math.min(cap, n));
        did = true;
      }
    }
  }
  // 配给制: a sale pays `gain` more, at most `cap` a round. The counter is keyed by the round number, so the cap
  // resets itself every round without needing an onRoundStart hook on the card.
  if (spec.sellBonus && isPos(spec.sellBonus.gain)) {
    if (ctx.event()?.piece && ctx.event().piece.kind === 'chess') {
      const cap = Number.isInteger(spec.sellBonus.cap) && spec.sellBonus.cap > 0 ? spec.sellBonus.cap : Infinity;
      const key = `${HEX_KEY}${id}:sold:${ctx.round}`;
      const paid = ctx.counter(key);
      if (paid < cap) {
        ctx.incCounter(key, 1);
        ctx.addFunds(spec.sellBonus.gain, 'hex');
        did = true;
      }
    }
  }
  // 军需官: a level-up refunds `pct`% of the price just paid (the hook event carries it).
  if (spec.levelRefund && isPos(spec.levelRefund.pct)) {
    const price = Number(ctx.event()?.price);
    if (Number.isFinite(price) && price > 0) {
      const back = Math.floor((price * spec.levelRefund.pct) / 100);
      if (back > 0) { ctx.addFunds(back, 'hex'); did = true; }
    }
  }
  // 盟约之主: the own most-numerous bond needs N fewer operators (the 调和 mechanism, PlayerState.bondCountBonus). The
  // bonus is re-picked every round start: clear the previous one first, so it follows the board.
  if (isPos(spec.mainBondCount)) {
    const list = Array.isArray(ctx.gd.bondIds) ? ctx.gd.bondIds : [];
    for (const bondId of list) {
      const flag = `${HEX_KEY}${id}:main:${bondId}`;
      if (ctx.counter(flag) > 0) { ctx.setBondCountBonus(bondId, 0); ctx.setCounter(flag, 0); }
    }
    let best = null;
    let bestCount = 0;
    for (const bondId of list) {
      const st = ctx.bond(bondId);
      const c = st && Number.isFinite(st.count) ? st.count : 0;
      if (c > bestCount) { bestCount = c; best = bondId; }
    }
    if (best) { ctx.setBondCountBonus(best, spec.mainBondCount); ctx.setCounter(`${HEX_KEY}${id}:main:${best}`, 1); }
    did = true;
  }
  // ---- third batch (0.3.0 playtest #3) ---------------------------------------------------------------
  // 因小失大: 附加盟约 (= 小盟约) need `small` more members, 核心盟约 (= 大盟约) `big` (negative = harder). 调和 and 独行
  // are left out: 调和 is the count mechanism itself and 独行 is a downward bond ("exactly one") the shift would break.
  if (spec.bondCountShift && typeof spec.bondCountShift === 'object') {
    const small = Number.isFinite(spec.bondCountShift.small) ? Math.trunc(spec.bondCountShift.small) : 0;
    const big = Number.isFinite(spec.bondCountShift.big) ? Math.trunc(spec.bondCountShift.big) : 0;
    const list = Array.isArray(ctx.gd.bondIds) ? ctx.gd.bondIds : [];
    for (const bondId of list) {
      if (bondId === 'maniShip' || bondId === 'soloShip') continue;
      const rec = ctx.gd.bond(bondId);
      if (!rec) continue;
      const v = rec.isCore ? big : small;
      if (!v) continue;
      ctx.setBondCountBonus(bondId, v);
      ctx.setCounter(`${HEX_KEY}${id}:shift:${bondId}`, v);
      did = true;
    }
  }
  // 层数转移: at battle start, half of the lowest active bond's layers move to the highest one — in this battle only
  // (the input snapshot the sim and the client both fight from), never in the persistent layers.
  if (spec.layerTransfer) {
    const input = ctx.event()?.input;
    const bonds = input && input.bonds && typeof input.bonds === 'object' ? input.bonds : null;
    if (bonds) {
      const active = Object.entries(bonds).filter(([, b]) => b && b.active && Number.isFinite(b.layers) && b.layers > 0);
      if (active.length >= 2) {
        active.sort((a, b) => a[1].layers - b[1].layers);
        const low = active[0];
        const high = active[active.length - 1];
        const move = low[0] !== high[0] ? Math.floor(low[1].layers / 2) : 0;
        if (move > 0) { low[1].layers -= move; high[1].layers += move; did = true; }
      }
    }
  }
  // 商店契约: a refresh arms the discount, the first operator bought afterwards spends it (onPrice stays pure: it only
  // reads the counter, which the private view / the audit may ask for any number of times).
  if (spec.shopContractArm) { ctx.setCounter(`${HEX_KEY}${id}:armed`, 1); did = true; }
  if (spec.shopContractSpend) {
    if (ctx.event()?.kind === 'chess') ctx.setCounter(`${HEX_KEY}${id}:armed`, 0);
    did = true;
  }
  if (isPos(spec.shopContractDiscount)) {
    if (ctx.event()?.kind === 'chess' && ctx.counter(`${HEX_KEY}${id}:armed`) > 0) {
      ctx.modifyPrice(-spec.shopContractDiscount);
      did = true;
    }
  }
  // 精英共鸣: 5x % per elite operator on the board to promote the operator just bought (x = the elite count)
  if (spec.eliteBuy && isPos(spec.eliteBuy.pctPerElite)) {
    const piece = ctx.event()?.piece;
    if (piece && piece.kind === 'chess' && Number.isInteger(piece.uid)) {
      const elites = (ctx.board() || []).filter((p) => p && p.kind === 'chess' && p.golden).length;
      const p = Math.min(1, (spec.eliteBuy.pctPerElite * elites) / 100);
      if (elites > 0 && ctx.rng() < p && ctx.promote(piece.uid)) did = true;
    }
  }
  // 装备转化: a discarded (g.destroy) item pays its own price back
  if (spec.itemRefund) {
    const ev = ctx.event();
    const piece = ev && ev.item;
    if (piece && typeof piece.id === 'string' && ev.reason === 'player' && typeof ctx.gd.itemPrice === 'function') {
      const price = ctx.gd.itemPrice(piece.id);
      if (isPos(price)) { ctx.addFunds(price, 'hex'); did = true; }
    }
  }
  // 远见透支: every purchase the 远见 discount actually reached costs `lp` life (never lethal: 1 is the floor)
  if (spec.foresightDebt && isPos(spec.foresightDebt.lp)) {
    const ev = ctx.event();
    if (ev && ev.kind === 'chess' && ctx.bondActive('visiShip') && typeof ctx.spendLp === 'function') {
      const tier = ctx.counter('bondaddon:visi:disc');
      const p = bondBuff(ctx, 'visiShip', 'bond_multi_layer_char_goods_price_bond_discount');
      const disc = Number(p.discount) || 0;
      let reached = tier >= 2;
      if (!reached && tier === 1) {
        const rec = ctx.chessRecord(ev.slot && ev.slot.id);
        reached = !!(rec && Array.isArray(rec.bonds) && rec.bonds.includes(p.bond || 'visiShip'));
      }
      if (disc > 0 && reached) { ctx.spendLp(spec.foresightDebt.lp); did = true; }
    }
  }
  // ---- eighth batch (the owner's list of 2026-10-12, §29.23) -----------------------------------------
  // 虚空形态: the pick empties the purse outright, and every LATER round arms one free spend — the pick's own round is
  // held back with `-1`, so the first free spend is the round after the pick, exactly as the card text says.
  if (spec.zeroFunds) {
    ctx.zeroFunds();
    ctx.setCounter(`${HEX_KEY}${id}:pickRound`, roundOf(ctx));
    ctx.setCounter(`${HEX_KEY}${id}:freeSpend`, 0);
    did = true;
  }
  if (spec.freeSpendArm) {
    const k = `${HEX_KEY}${id}:freeSpend`;
    ctx.setCounter(k, roundOf(ctx) > ctx.counter(`${HEX_KEY}${id}:pickRound`) ? 1 : 0);
    did = true;
  }
  if (spec.freeSpendRefund) {
    const k = `${HEX_KEY}${id}:freeSpend`;
    const amt = Number(ctx.event()?.amount);
    if (ctx.counter(k) > 0) {
      ctx.setCounter(k, 0);
      if (amt > 0) ctx.addFunds(Math.trunc(amt), 'hex');
      did = true;
    }
  }
  // 天人形态: `freeLevelUps.step` free 调度中心 levels at the start of each prep, the count growing by `step` every
  // round (1, 2, 3 …). The counter holds what THIS round's grant is worth, so the second grant is 2.
  // NOTE the hook: `onPrepStart`, not `onRoundStart` — a level-up is phase-gated (PlayerState `_gate` needs PREP), and
  // `onRoundStart` is dispatched while the match is still in ROUND_START (MatchPhases), where every action would be
  // refused. Owner report of 2026-10-12 (恶魔形态 never took over, same cause).
  if (spec.freeLevelUps) {
    const k = `${HEX_KEY}${id}:freeLevels`;
    const n = ctx.counter(k) + countOf(spec.freeLevelUps.step, 1);
    ctx.setCounter(k, n);
    for (let i = 0; i < n; i++) if (!ctx.levelUpFree()) break;
    did = true;
  }
  // 恶魔形态 (the prep half): the AI plays this round's SPENDING — 调度中心 first, then buys and refreshes until the
  // funds run out. Placement and equipment stay the player's own (server/match/bot.js `botSpendOnly`). Same hook note
  // as 天人形态: everything it does is phase-gated, so it has to run at the start of the PREP, and `everyPreps`
  // throttles it the way `everyRounds` throttles an onRoundStart spec (that throttle only exists on onRoundStart).
  if (spec.demonTakeover) {
    const every = Number.isInteger(spec.everyPreps) && spec.everyPreps > 1 ? spec.everyPreps : 1;
    const due = every > 1 ? (ctx.incCounter(`${HEX_KEY}${id}:preps`, 1) - 1) % every === 0 : true;
    if (due) ctx.demonTakeover();
    did = true;
  }
  // 群蛇形态: every sale banks `per` enemy-points …
  if (spec.serpentPoints && isPos(spec.serpentPoints.per)) {
    ctx.incCounter(`${HEX_KEY}${id}:serpent`, spec.serpentPoints.per);
    did = true;
  }
  // … and when a battle is built the integer part is cashed in as that many enemies killed at its start. The count
  // rides the ref's own params (`serpentKills.count`), which the sim's install() reads; the points are spent here.
  if (spec.serpentArm) {
    const ref = ctx.effect(`hex:${id}`);
    const cfg = (ref && ref.params && ref.params.serpentKills) || {};
    const perPoint = isPos(cfg.perPoint) ? cfg.perPoint : 1;
    const k = `${HEX_KEY}${id}:serpent`;
    const pts = ctx.counter(k);
    const whole = Math.floor(pts);
    const kills = whole * perPoint;
    if (ref) ctx.addEffect({ id: `hex:${id}`, params: { ...(ref.params || {}), serpentKills: { perPoint, count: kills } } });
    // the battle input carries its own COPY of the ref (it was built before onBattleStart ran) — patch that one too, so
    // the sim sees the number whichever side simulates the battle
    const ev = ctx.event();
    const list = ev && ev.input && Array.isArray(ev.input.playerEffects) ? ev.input.playerEffects : null;
    const inRef = list ? list.find((r) => r && (r.key === `hex:${id}` || (r.data && r.data.hexId === id))) : null;
    if (inRef && inRef !== ref) inRef.params = { ...(inRef.params || {}), serpentKills: { perPoint, count: kills } };
    ctx.setCounter(k, pts - whole);
    did = true;
  }
  // ---- eleventh batch (the owner's own list of 2026-10-13, §29.34) -------------------------------------------
  // 盟约棱镜: once per DISTINCT non-core bond among the board operators, every CORE bond gains `per` layers. The board
  // pieces are read through `ctx.chessRecord` (the pieces' own ids), so a 变形同构体-granted bond counts like any other.
  if (spec.prismLayers && isPos(spec.prismLayers.per)) {
    const per = countOf(spec.prismLayers.per, 3);
    const seen = new Set();
    for (const p of ctx.board() || []) {
      if (!p || p.kind !== 'chess' || typeof p.id !== 'string') continue;
      const rec = typeof ctx.chessRecord === 'function' ? ctx.chessRecord(p.id) : null;
      for (const b of (rec && Array.isArray(rec.bonds) ? rec.bonds : [])) {
        const bond = ctx.gd.bond(b);
        if (bond && !bond.isCore) seen.add(b);
      }
    }
    if (seen.size) {
      // every CORE bond in data order (active or not — a layer banked before the bond activates still counts, [ASSUMED]):
      // the card's text names 「你的核心盟约」 without an activation condition.
      for (const b of (Array.isArray(ctx.gd.bondIds) ? ctx.gd.bondIds : [])) {
        const bond = ctx.gd.bond(b);
        if (bond && bond.isCore) ctx.addLayers(b, seen.size * per, { reason: 'hex' });
      }
      did = true;
    }
  }
  // 紧急拨款: an ELITE sale pays `funds` at once and arms the next refresh's guaranteed slot. The sold piece is the RAW
  // piece (`{ uid, kind, id, … }` — the event carries no `golden`), so elite-ness is read off the record.
  if (spec.eliteGrant && ctx.event() && ctx.event().piece && ctx.event().piece.kind === 'chess') {
    const piece = ctx.event().piece;
    if (typeof ctx.gd.isGolden === 'function' && ctx.gd.isGolden(piece.id)) {
      ctx.addFunds(isPos(spec.eliteGrant.funds) ? spec.eliteGrant.funds : 6, 'hex');
      ctx.setCounter(`${HEX_KEY}${id}:nextTopBond`, 1);
      did = true;
    }
  }
  // … the armed slot: the next refresh shows one operator of the own most-numerous bond (the arm is spent only by a
  // refresh that actually wrote the card).
  if (spec.eliteGrantRefresh) {
    const k = `${HEX_KEY}${id}:nextTopBond`;
    if (ctx.counter(k) > 0) {
      if (guaranteeTopBondSlot(ctx)) ctx.setCounter(k, 0);
      did = true;
    }
  }
  // 均衡盟约: every ACTIVE bond that HOLDS layers is set to the rounded-up average of their total (向上取整). One such
  // bond does nothing. A noStack bond (独行 / 绝技 / 调和 / 协防干员) takes no part at all — it neither feeds the pool nor
  // receives a share (holdsLayers above; 业主 2026-10-14).
  if (spec.bondEqualize) {
    const active = Object.entries(ctx.bonds()).filter(([bondId, b]) => b && b.active && holdsLayers(ctx, bondId));
    if (active.length >= 2) {
      const total = active.reduce((s, [, b]) => s + (Number(b.layers) || 0), 0);
      const each = Math.ceil(total / active.length);
      for (const [bondId] of active) ctx.setLayers(bondId, each, { reason: 'hex' });
      did = true;
    }
  }
  // 背水一战 (the prep half): while the own LP is BELOW the card's threshold, the first refresh of the round is free.
  // The ×layerMul half lives in `layerGainMulOf` (prep) and the battle's `layerGain` hook — both read the SAME spec.
  if (spec.lastDitchRefresh) {
    const ld = (hex && hex.effect && hex.effect.lastDitch) || {};
    const lpBelow = isPos(ld.lpBelow) ? ld.lpBelow : 5;
    const lp = typeof ctx.lp === 'function' ? ctx.lp() : Infinity;
    if (ld.freeRefresh !== false && Number.isFinite(lp) && lp < lpBelow) { ctx.grantFreeRefresh(1); did = true; }
  }
  // … and the arm the SIM reads: the match stamps whether the window is open at this battle's start (the sim has no LP),
  // on the ref AND on the battle input's own copy (built before this dispatch — the 群蛇形态 convention).
  if (spec.lastDitchArm) {
    const ld = (hex && hex.effect && hex.effect.lastDitch) || {};
    const lpBelow = isPos(ld.lpBelow) ? ld.lpBelow : 5;
    const lp = typeof ctx.lp === 'function' ? ctx.lp() : Infinity;
    const active = Number.isFinite(lp) && lp < lpBelow;
    const ref = ctx.effect(`hex:${id}`);
    const stamped = { ...(ref && ref.params ? ref.params : {}), lastDitch: { ...ld, active } };
    if (ref) ctx.addEffect({ id: `hex:${id}`, params: stamped });
    const ev = ctx.event();
    const list = ev && ev.input && Array.isArray(ev.input.playerEffects) ? ev.input.playerEffects : null;
    const inRef = list ? list.find((r) => r && (r.key === `hex:${id}` || (r.data && r.data.hexId === id))) : null;
    if (inRef && inRef !== ref) inRef.params = { ...stamped };
    did = true;
  }
  // 盟约寄生: at battle start, every chess in the 整备区 (hand) gives the highest ACTIVE bond `per` layers. They are real,
  // persistent layers AND are patched into this battle's own input snapshot (built before this dispatch), so the fight
  // that is starting sees them — the 层数转移 / 群蛇形态 convention.
  if (spec.parasiteLayers && isPos(spec.parasiteLayers.per)) {
    const per = countOf(spec.parasiteLayers.per, 2);
    const bench = (typeof ctx.hand === 'function' ? ctx.hand() || [] : []).filter((p) => p && p.kind === 'chess').length;
    const top = typeof ctx.topLayerBond === 'function' ? ctx.topLayerBond() : null;
    if (bench > 0 && top) {
      const add = ctx.addLayers(top, bench * per, { reason: 'hex' });
      const input = ctx.event() && ctx.event().input;
      const snap = input && input.bonds && input.bonds[top];
      if (snap && Number.isFinite(add) && add > 0) snap.layers = (Number(snap.layers) || 0) + add;
      did = true;
    }
  }
  // 三连透支: merging an elite operator grants one ELITE operator of the board's most-numerous bond, and the card then
  // lapses FOR THAT ROUND (业主 2026-10-14: 「…然后本回合失效」; it used to lapse for the whole match). The merge event
  // carries the fresh elite piece (`ev.kind === 'chess'`); an in-place 升华 promotion is not heard here (it dispatches no
  // onMerge) — 「合成精锐干员」 is the merge.
  //
  // The counter is keyed by the round number, exactly like 配给制's sell cap: the cap clears itself every round with no
  // `onRoundStart` hook on the card, and a saved match keeps counting rounds the same way.
  if (spec.eliteBondGrant && ctx.event() && ctx.event().kind === 'chess') {
    const k = `${HEX_KEY}${id}:eliteGrant:${ctx.round}`;
    if (ctx.counter(k) < 1) {
      const top = typeof ctx.topMemberBond === 'function' ? ctx.topMemberBond() : null;
      const cid = top ? ctx.rollChess({ bond: top, ignoreCounts: true }) : null;
      const got = cid ? ctx.grantChess(cid, { golden: true, source: 'hex' }) : null;
      if (got) { ctx.setCounter(k, 1); did = true; }
    }
  }
  // 升级刷新 (the onPrice half): every operator costs `buyDiscount` less, always. onPrice stays PURE — it only reads the
  // card's own params, exactly like 商店契约's discount.
  if (spec.shopTunePrice && ctx.event() && ctx.event().kind === 'chess') {
    const st = (hex && hex.effect && hex.effect.shopTune) || {};
    const disc = isPos(st.buyDiscount) ? Math.trunc(st.buyDiscount) : 1;
    ctx.modifyPrice(-disc);
    did = true;
  }
  // … and the onRefresh half: `refreshPrice` is read by `PlayerState.refreshPriceNow` (the override is the spec itself),
  // so only the guaranteed slot is left here — the FIRST refresh of each round shows one operator of the own
  // most-numerous bond (`roundStats().refreshes` is bumped before this dispatch, so 1 = the round's first).
  if (spec.shopTuneRefresh) {
    const st = (hex && hex.effect && hex.effect.shopTune) || {};
    if (st.firstRefreshTopBond) {
      const n = typeof ctx.roundStats === 'function' ? Number(ctx.roundStats().refreshes) || 0 : 1;
      if (n <= 1) guaranteeTopBondSlot(ctx);
    }
    did = true;
  }
  // 电表倒转·改: on a FREE refresh (奇迹), that chance that every operator this refresh shows costs 0.
  if (spec.miracleZeroCostPct) {
    const pct = Number(spec.miracleZeroCostPct);
    const ev = ctx.event();
    if (pct > 0 && ev && ev.free === true && ctx.rng() < pct / 100) { ctx.freeShopChess(); did = true; }
  }
  // ---- tenth batch (the owner's list of 2026-10-15): the two PREP-side cards --------------------------------
  // 潘多拉魔盒: every hex the player owns — THIS one included — is replaced by a random 3阶 hex. The card's own text
  // names 3阶, so the roll is restricted to `prismatic` (the rarity whose tier is 3); a player who owns nothing but
  // this card still gets one, because the pick itself is already in `ps.effects` by the time onPick runs.
  //
  // REPLACEMENT, not addition: the old refs are dropped and the new ones granted through the ordinary `applyHex`
  // path (server/match/hextech.js), which is what re-runs each new card's own onPick. `ctx.replaceHexes` is that
  // path — it lives in the match layer because the ctx has no way to re-enter the pick pipeline.
  if (spec.pandora) {
    if (typeof ctx.replaceHexes === 'function') { ctx.replaceHexes(); did = true; }
  }
  // 可露希尔大降价: the next `refreshes` refreshes of THIS round are free, and so is every purchase made **within that
  // window** — the owner's ruling of 2026-10-18 「免费购买是在三次刷新内有效」 (not 「3 次购买」, not the whole round).
  // So there are two things to open, both player-level:
  //   * `grantFreeRefresh(refreshes)` — the existing free-refresh pool that pays for those refreshes;
  //   * `openFreeBuyWindow(refreshes)` — economy.js priceOf reads it while > 0, economy.js refresh() spends one per
  //     refresh, round.js startRound closes it (the card says 本回合内).
  //
  // Fix 2026-10-18 (owner report 「只免费第一次，刷新后都不免费」): the buy half used to mark the CURRENT shop's slots
  // free, which paid out once — the next refresh rebuilt the slots and every purchase cost again. 电表倒转·改's own
  // `freeShopChess` (a single FREE refresh's slots) stays what it is; that one really is per-refresh.
  if (spec.discount) {
    const n = (v) => (Number.isFinite(Number(v)) ? Math.max(0, Math.trunc(Number(v))) : 0);
    const refreshes = n(spec.discount.refreshes);
    if (refreshes > 0) { ctx.grantFreeRefresh(refreshes); did = true; }
    // the roster's `buys` (3) is the authored statement of what the window covers; the window itself IS the refreshes
    if (refreshes > 0 && typeof ctx.openFreeBuyWindow === 'function') { ctx.openFreeBuyWindow(refreshes); did = true; }
  }
  void hook;
  return did;
}

/**
 * Rewrite the shop's FIRST slot with an operator of the own most-numerous bond (紧急拨款 / 升级刷新). Returns whether a
 * piece landed: no top bond, no pool candidate of that bond at the current 调度中心 level, or a refused slot all leave the
 * shop untouched — and the caller then keeps its arm, so the card pays out on the next refresh instead of wasting it.
 */
function guaranteeTopBondSlot(ctx) {
  if (typeof ctx.topMemberBond !== 'function' || typeof ctx.setShopSlot !== 'function') return false;
  const top = ctx.topMemberBond();
  if (!top) return false;
  const id = typeof ctx.rollChess === 'function' ? ctx.rollChess({ bond: top, maxTier: typeof ctx.shopLevel === 'function' ? ctx.shopLevel() : 6 }) : null;
  return !!id && !!ctx.setShopSlot(0, { kind: 'chess', id });
}

/** `{ ...bb, ...bbStr }` of a bond buff from the match data (the same lookup as bonds/addon/meta.js `buff`). */
function bondBuff(ctx, bondId, key) {
  const rec = ctx.data && ctx.data.bonds ? ctx.data.bonds[bondId] : null;
  for (const b of (rec && Array.isArray(rec.buffs) ? rec.buffs : [])) if (b && b.key === key) return { ...(b.bb || {}), ...(b.bbStr || {}) };
  return {};
}

/** Dispatcher hooks a player hex may declare. onPrice is offered since 0.3.0 playtest #3 (商店契约 / 远见透支). */
export const HEX_HOOKS = Object.freeze([
  'onIncome', 'onPrepStart', 'onPrepEnd', 'onGain', 'onSold', 'onRefresh', 'onBuy', 'onSpend', 'onMerge', 'onLevelUp',
  'onBattleStart', 'onBattleResult', 'onChoicePick', 'onEquip', 'onArt', 'onDestroy', 'onLayers', 'onPrice',
]);

/** The `hex:<id>` handler of one player hex. */
function handlerOf(hex) {
  const h = {
    /**
     * The immediate part runs for THIS card's OWN pick only. `applyHex` (server/match/hextech.js) re-dispatches the
     * `onHexPick` event to every OTHER persistent effect the player owns — so garrisons / items / bands / globals can
     * observe the pick — and every hex handler carries an `onHexPick` (it is unconditional below), so without this guard
     * each already-owned card re-ran its `onPick` on every later pick: 战备津贴 paid again, 后勤整备 / 幽魂形态 handed
     * out another item, 二次抽取 cascaded, 虚空形态 emptied the purse a second time. Owner report of 2026-10-12
     * (test field): 「获得幽魂形态后，每获得一个协议源石都会再给一个装备幽魂」.
     */
    onHexPick(ctx) {
      const ev = typeof ctx.event === 'function' ? ctx.event() : null;
      const picked = ev && ev.hex && typeof ev.hex.id === 'string' ? ev.hex.id : null;
      if (picked && picked !== hex.id) return false;
      return applySpec(ctx, hex.effect && hex.effect.onPick, hex, 'onHexPick');
    },
    onRoundStart(ctx) {
      const spec = hex.effect && hex.effect.onRoundStart;
      if (!spec) return false;
      const every = Number.isInteger(spec.everyRounds) && spec.everyRounds > 1 ? spec.everyRounds : 1;
      if (every > 1) {
        const n = ctx.incCounter(`${HEX_KEY}${hex.id}:rounds`, 1);
        if ((n - 1) % every !== 0) return false;
      }
      return applySpec(ctx, spec, hex, 'onRoundStart');
    },
  };
  // any other dispatcher hook the hex declares (0.3.0 playtest #2): onSpend / onSold / onBattleResult / …
  for (const hook of HEX_HOOKS) {
    const spec = hex.effect && hex.effect[hook];
    if (spec && typeof spec === 'object') h[hook] = (ctx) => applySpec(ctx, spec, hex, hook);
  }
  return h;
}

/**
 * Battle passives of one EffectRef's params (`effect.battle`), or null. `aspdPct`/`aspd` is ASPD POINTS (the flat `aspd`
 * stat: interval = bat × 100 / aspd), everything else is a percentage turned into the additive 直接乘算 buckets.
 *
 * The fourth batch (2026-10-09) widened this table: `blockCnt` (盾墙), `spRecoveryFlat` (教官批注) and `spCostFlat`
 * (超载协议) are flat mods on non-percentage stats, so they are copied through verbatim like `resFlat` and `aspd`.
 * `directMods` only builds the three ratio buckets (atk / def / hp) — anything else has to be added here.
 */
export function battleModsOf(params) {
  const b = params && params.battle;
  if (!b || typeof b !== 'object') return null;
  const mods = directMods({ atk: pct(b.atkPct), def: pct(b.defPct), hp: pct(b.maxHpPct) });
  const aspd = isPos(b.aspd) ? b.aspd : b.aspdPct; // `aspdPct` is the v0.3.0 name, kept for an already-saved data set
  if (isPos(aspd)) mods.aspd = aspd;
  if (Number.isFinite(b.resFlat) && b.resFlat !== 0) mods.resFlat = b.resFlat;
  if (Number.isFinite(b.blockCnt) && b.blockCnt !== 0) mods.blockCnt = b.blockCnt;
  if (Number.isFinite(b.spRecoveryFlat) && b.spRecoveryFlat !== 0) mods.spRecoveryFlat = b.spRecoveryFlat;
  if (Number.isFinite(b.spCostFlat) && b.spCostFlat !== 0) mods.spCostFlat = b.spCostFlat;
  return Object.keys(mods).length ? mods : null;
}

/** Prep-side registration (server boot): one handler per player hex of data/hextech.json. */
export function registerMeta(registry) {
  const d = hexData();
  const player = d && d.playerHexes ? d.playerHexes : null;
  if (!player) return;
  for (const hex of Object.values(player)) {
    if (!hex || typeof hex.id !== 'string' || typeof registry.hex !== 'function') continue;
    registry.hex(hex.id, handlerOf(hex));
  }
  // 债务 (sixth batch, 2026-10-11): the ONE card of the batch whose mechanic lives in the prep phase and on ANOTHER
  // player. server/match/hextech.js `applyHexExtras` picks the teammate at pick time, pays them and pushes this
  // watcher onto THEIR effects (`effect:hexdebt`) — the dispatcher only ever runs a player's own effects, so the
  // observer has to sit on the buyer, not on the picker. It reads its own `params` (ownerId / untilRound) and never
  // the hex record, so a saved match from before this batch simply has no such ref.
  if (typeof registry.register === 'function') registry.register(DEBT_EFFECT_KEY, DEBT_HANDLER);
}

/** The `effect:` key of 债务's watcher (server/match/hextech.js pushes the ref). */
export const DEBT_EFFECT_KEY = 'effect:hexdebt';

/**
 * 债务's watcher, run on the CHOSEN TEAMMATE's dispatch:
 *   onBuy        — that teammate bought an operator while the window is open ⇒ the picker gains an identical one;
 *   onRoundStart — once the window has passed, the watcher removes itself (the card's 「3回合内」).
 * `params = { ownerId, hexId, untilRound }`; a missing untilRound means "no window" (never expires).
 */
export const DEBT_HANDLER = Object.freeze({
  onBuy(ctx, ev) {
    const ref = ctx.source && ctx.source.ref;
    const p = (ref && ref.params) || {};
    if (Number.isFinite(p.untilRound) && ctx.round > p.untilRound) { ctx.removeEffect(ref.id); return; }
    if (!ev || ev.kind !== 'chess' || !ev.piece || typeof ev.piece.id !== 'string') return;
    const owner = ctx.player(p.ownerId);
    if (!owner) return;                      // the picker is gone: the card has nobody to pay
    // the identical operator, through the ordinary grant path (a full 整备区 / an empty pool simply grants nothing)
    owner.grantChess(ev.piece.id, { source: 'hex_debt', toast: false });
  },
  onRoundStart(ctx) {
    const ref = ctx.source && ctx.source.ref;
    const p = (ref && ref.params) || {};
    if (Number.isFinite(p.untilRound) && ctx.round > p.untilRound) ctx.removeEffect(ref.id);
  },
});

/**
 * Battle side: every hex the field's players own, as persistent operator passives from battle start on, plus the
 * scripted battle parts: 先锋之势's first kill by a PIONEER pays coins through the bounty channel (`battle.addCoins` →
 * the battle result's `coins` → the player's next prep, server/match/match/settle.js); 传承's accumulated per-bond ATK
 * bonus reaches only the operators that actually share a sold bond; and the 0.3.0 playtest #3 batch —
 * 击倒馈赠 (a stacking ATK buff per knock-out), 技能层涌 (a skill opening adds layers to the caster's active bonds),
 * 北境长城 (a growing shield on the rightmost own column), 装甲破坏 (physical hits shred the enemy's DEF), 精准穿透
 * (the 精准 layers become DEF/RES penetration for 精准 and every ranged operator), 深度吞噬 (the devour grants the
 * devourer +1 attack target), 不屈余烬 (a 4 s HP floor after 不屈 fired) and 盟约裂变 (the two kept bonds gain ×3
 * layers).
 *
 * A hex lapses with `params.expireRound` (孤注一掷's four rounds): the ref is skipped once `battle.round` passed it.
 * Refs whose `data.hexId` names an ownership-only mechanic (they carry no stats themselves) are collected per player.
 */
export function install(battle) {
  // The ENEMY side first: a field with no player hexes still has to run the enemy's verb cards, and install() returns
  // early below when neither side owns anything (DESIGN §29.10).
  installEnemyVerbs(battle);
  // The fifth batch's four scripts (server/sim/content/hexcards/**): they read the same effect refs the block below
  // scans, but through the shared hook bundle, and they register their own handlers. Dispatched here, before the early
  // return, so a field whose ONLY cards are these four still installs them.
  installHexCards(battle);
  const refs = [];
  /** @type {Map<string, Set<string>>} playerId → the hex ids it owns (every hex, stats or not) */
  const owned = new Map();
  for (const ps of battle.players || []) {
    if (!ps || typeof ps.playerId !== 'string') continue;
    const set = new Set();
    for (const ref of ps.playerEffects || []) {
      if (!ref || typeof ref.key !== 'string' || !ref.key.startsWith(HEX_KEY)) continue;
      const hexId = ref.data && typeof ref.data.hexId === 'string' ? ref.data.hexId : ref.key.slice(HEX_KEY.length);
      set.add(hexId);
      const expire = ref.params && ref.params.expireRound;
      if (Number.isFinite(expire) && Number.isFinite(battle.round) && battle.round > expire) continue;
      const mods = battleModsOf(ref.params);
      const bondAtk = ref.params && ref.params.battle && ref.params.battle.bondAtk ? ref.params.battle.bondAtk : null;
      const firstKillBy = ref.params && ref.params.battle && ref.params.battle.firstKillBy ? ref.params.battle.firstKillBy : null;
      const firstAttackBy = ref.params && ref.params.battle && ref.params.battle.firstAttackBy ? ref.params.battle.firstAttackBy : null;
      const extraCharges = ref.params && ref.params.battle && isPos(ref.params.battle.extraCharges) ? Math.trunc(ref.params.battle.extraCharges) : null;
      if (mods || bondAtk || firstKillBy || firstAttackBy || extraCharges) refs.push({ pid: ps.playerId, ref, mods, bondAtk, firstKillBy, firstAttackBy, extraCharges });
    }
    if (set.size) owned.set(ps.playerId, set);
  }
  if (!refs.length && !owned.size) return;
  const ownersOf = (hexId) => [...owned.entries()].filter(([, s]) => s.has(hexId)).map(([pid]) => pid);
  const opsOf = (pid) => battle.allyUnits.filter((u) => u && u.kind === 'op' && u.side === 'ally' && u.ownerId === pid);
  /** The `spec` of an ownership-only mechanic (the effect record of the hex). */
  const specOf = (pid, hexId, key) => {
    const ref = (battle.getPlayer(pid)?.playerEffects || []).find((e) => e && (e.data?.hexId === hexId || e.key === `${HEX_KEY}${hexId}`));
    const spec = ref && ref.params ? ref.params[key] : null;
    return spec && typeof spec === 'object' ? spec : {};
  };

  if (refs.length) {
    battle.on('battleStart', () => {
      for (const { pid, ref, mods, bondAtk } of refs) {
        const key = typeof ref.id === 'string' ? ref.id : ref.key;
        for (const u of opsOf(pid)) {
          if (mods) passiveBuff(battle, u, key, { ...mods });
          if (bondAtk) {
            // only the operators carrying one of the bonds the player sold into get the stacked bonus
            const bonds = Array.isArray(u.def && u.def.bonds) ? u.def.bonds : [];
            const sum = bonds.reduce((s, b) => s + (Number(bondAtk[b]) || 0), 0);
            if (sum > 0) passiveBuff(battle, u, `${key}:bond`, { atkPct: sum / 100 });
          }
        }
      }
    }, { priority: -10 });
  }
  for (const { pid, firstKillBy } of refs) {
    if (!firstKillBy || !isPos(firstKillBy.coins) || typeof firstKillBy.profession !== 'string') continue;
    let fired = false;
    battle.on('kill', ({ killer, victim }) => {
      if (fired || !victim || victim.side !== 'enemy') return;
      fired = true;
      if (killer && killer.def && killer.def.profession === firstKillBy.profession) battle.addCoins(pid, firstKillBy.coins);
    });
  }
  // ---- 先锋之势 (the second half, owner 2026-10-12): each own operator of the profession buffs ITSELF +atkPct for
  // `seconds` on its OWN first attack of the battle. The once-per-battle flag rides `u.mem` (the 不屈余烬 / 复活
  // convention: it survives a death and a redeploy), so an operator that dies and comes back is not paid twice.
  for (const { pid, firstAttackBy } of refs) {
    if (!firstAttackBy || !isPos(firstAttackBy.atkPct) || typeof firstAttackBy.profession !== 'string') continue;
    const seconds = isPos(firstAttackBy.seconds) ? firstAttackBy.seconds : 10;
    battle.on('attack', ({ attacker }) => {
      const u = attacker;
      if (!u || !isOp(u) || u.ownerId !== pid) return;
      if (!(u.def && u.def.profession === firstAttackBy.profession)) return;
      if (u.mem.hexVanguardAtk) return;
      u.mem.hexVanguardAtk = true;
      battle.addBuff(u, { key: 'hex:vanguard', duration: seconds, mods: { atkPct: pct(firstAttackBy.atkPct) }, visible: true, tags: ['hex'] });
    });
  }

  // ---- 击倒馈赠: every knock-out stacks +atkPct on the operator that made it (battle-long, survives a redeploy) ----
  for (const pid of ownersOf('hex_killgift')) {
    const atkPct = pct(specOf(pid, 'hex_killgift', 'killGift').atkPct);
    if (!(atkPct > 0)) continue;
    battle.on('kill', ({ killer, victim }) => {
      if (!killer || killer.side !== 'ally' || killer.kind !== 'op' || killer.ownerId !== pid) return;
      if (!victim || victim.side !== 'enemy') return;
      battle.addBuff(killer, { key: 'hex:killgift', refresh: 'stack', stacks: 1, maxStacks: 999, mods: { atkPct }, persist: true, allowDead: true, tags: ['hex'] });
    });
  }

  // ---- 技能层涌: opening a skill adds `layers` to every active bond the caster belongs to (IN_BATTLE, so it settles).
  // Owner's cap (2026-10-14, replacing the 20-openings cap of the day before): `maxLayersPerBond` (40) bounds how many
  // layers THIS CARD may stack on ONE bond in one battle — a battle IS one round (`Battle.round`), so the tally lives in
  // the handler's own closure (a fresh install per field). It is per BOND, not global: a caster in three bonds may feed
  // all three, each on its own budget.
  //
  // The tally counts what the card REQUESTS, not what lands: other mechanics that multiply a gain (背水一战's ×2 on the
  // `layerGain` hook) or the bond's own 999 cap apply on top, exactly as they do for every other layer source. Counting
  // the landed amount instead would make those multipliers eat this card's own budget and stop it short of 40.
  // Without the key (an old save / a hand-built ref) the card stays uncapped, exactly as before.
  for (const pid of ownersOf('hex_skillflow')) {
    const spec = specOf(pid, 'hex_skillflow', 'skillFlow');
    const layers = countOf(spec.layers, 1);
    const perBond = Number.isFinite(Number(spec.maxLayersPerBond)) && Number(spec.maxLayersPerBond) > 0
      ? Math.trunc(Number(spec.maxLayersPerBond)) : Infinity;
    const spent = new Map();
    battle.on('skillStart', ({ unit }) => {
      if (!unit || unit.kind !== 'op' || unit.side !== 'ally' || unit.ownerId !== pid) return;
      for (const bondId of unitBonds(unit)) {
        if (!bondActive(battle, pid, bondId)) continue;
        const room = perBond - (spent.get(bondId) || 0);
        if (!(room > 0)) continue;
        const want = Math.min(layers, room);
        spent.set(bondId, (spent.get(bondId) || 0) + want);
        battle.addLayers(pid, bondId, want, 'hex');
      }
    });
  }

  // ---- 装甲破坏: any allied physical hit shreds 20 DEF off that enemy, stacking for the battle ----
  for (const pid of ownersOf('hex_armorbreak')) {
    const defFlat = Number(specOf(pid, 'hex_armorbreak', 'armorBreak').defFlat);
    if (!(defFlat > 0)) continue;
    battle.on('hit', (c) => {
      const src = c && c.source;
      if (!src || src.side !== 'ally' || src.ownerId !== pid || src.kind !== 'op') return;
      if (!c.target || c.target.side !== 'enemy' || !c.dmg || c.dmg.type !== 'phys') return;
      battle.addBuff(c.target, { key: 'hex:armorbreak', refresh: 'stack', stacks: 1, maxStacks: 100000, mods: { defFlat: -defFlat }, allowDead: true, visible: true, tags: ['hex'] });
    });
  }

  // ---- 深度吞噬: the devour gives the DEVOURER +1 attack target (owner 2026-10-12; it used to steal half the
  // devoured operator's DEF). `passiveBuff` replaces under one key, so a marker that devours twice stays at +1.
  for (const pid of ownersOf('hex_deepdevour')) {
    const s = specOf(pid, 'hex_deepdevour', 'devourTarget');
    const extra = Number.isFinite(Number(s.maxTargets)) ? Math.trunc(Number(s.maxTargets)) : 1;
    if (!(extra > 0)) continue;
    battle.on('devourGain', ({ marker }) => {
      if (!marker || marker.ownerId !== pid) return;
      passiveBuff(battle, marker, 'hex:deepdevour', { maxTargets: extra });
    });
  }

  // ---- 不屈余烬: after 不屈 redeploys an operator it gains +`block` block for `seconds`. The roster's numbers became
  // 6 s / +2 on 2026-10-13 (they were 4 s / +1); the defaults below only cover a hand-built ref.
  //
  // The HP floor (锁血) was REMOVED on 2026-10-14 (owner: 「不屈余烬去掉锁血」): the card used to arm a
  // `unit.mem.hexEmberUntil` window and hold it at 1 HP through a `fatal` handler, on top of the block. Only the block
  // half remains, so nothing here touches `fatal` any more — 不屈's own redeploy is again the only thing that keeps the
  // operator standing, and any other `fatal` consumer is unaffected (this handler never shared state with them).
  const ember = ownersOf('hex_indomember');
  if (ember.length) {
    const specs = new Map(ember.map((pid) => [pid, specOf(pid, 'hex_indomember', 'indomEmber')]));
    battle.on('bondTrigger', ({ bondId, unit }) => {
      if (bondId !== 'indomShip' || !unit || !specs.has(unit.ownerId)) return;
      const s = specs.get(unit.ownerId);
      const seconds = Number(s.seconds) > 0 ? Number(s.seconds) : 6;
      const block = Number.isFinite(Number(s.block)) ? Math.trunc(Number(s.block)) : 2;
      if (!(block > 0)) return; // a block-less spec would be a no-op card: arm nothing at all
      battle.addBuff(unit, { key: 'hex:indomember', duration: seconds, mods: { blockCnt: block }, visible: true, tags: ['hex'] });
    });
  }

  // ---- 不灭壁垒 (the second half, owner 2026-10-12): each own operator revives once per battle — items/battle.js
  // `reviveNow`, the 埃芒加德 / 阿戈尔 convention (the knock-out stands and its effects run, then the operator
  // redeploys at once, free, where it lies: full HP, SP reset, the deploy effects run). PRIO_HEX_REVIVE is last in
  // line, so a card that saves every operator is only spent for one nothing else could save; the per-operator flag
  // rides `u.mem`, which survives the redeploy.
  for (const pid of ownersOf('hex_immortal')) {
    const max = countOf(specOf(pid, 'hex_immortal', 'immortalRevive').count, 1);
    if (!(max > 0)) continue;
    battle.on('death', (c) => {
      const u = c && c.unit;
      if (!isOp(u) || !u.mem || u.ownerId !== pid) return;
      const used = Math.max(0, Math.trunc(Number(u.mem.hexImmortalRevives) || 0));
      if (used >= max) return;
      if (!reviveNow(battle, c, 'hex:immortal')) return;
      u.mem.hexImmortalRevives = used + 1;
      fxOn(battle, 'revive', u, 'hex:immortal', 'hex_immortal', { left: max - used - 1 });
    }, { priority: PRIO_HEX_REVIVE });
  }

  // ---- 回响形态 (owner 2026-10-12, §29.23): every own operator's skill gains `extraCharges` charges of headroom. The
  // Skill's own fields are what the SP/charge loop reads (server/sim/skills.js: the loop fills `charges` up to
  // `maxCharges`, and `ready` is `charges >= 1`), so this needs no buff key — and a skill that could not hold a charge
  // (kind 'instant', maxCharges 1) becomes a `charges` skill so it can hold one extra cast.
  //
  // A TIMED skill (duration / ammo / toggle) must keep its `kind`: `kind` is what `Skill.isTimed` (activate() takes the
  // timed branch and arms `timeLeft` only for it) and the duration branch of `Skill.tick()` read. Rewriting a timed
  // skill to 'charges' dropped it out of both, so its duration timer never ran and the cast ended at once — as an
  // instant on activation, or on the skill's first attack through `pending` (owner report, 2026-10-12: "持续技能直接结束").
  // Its extra charge is already granted by `maxCharges`, which is the only field the charge loop reads.
  for (const { pid, extraCharges } of refs) {
    const extra = Number.isFinite(Number(extraCharges)) ? Math.trunc(Number(extraCharges)) : 0;
    if (!(extra > 0)) continue;
    battle.on('battleStart', () => {
      for (const u of opsOf(pid)) {
        const sk = u && u.skill;
        if (!sk || sk.noSkill || sk.kind === 'passive') continue;
        sk.maxCharges = Math.max(1, Math.floor(Number(sk.maxCharges) || 1)) + extra;
        if (sk.kind !== 'charges' && !sk.isTimed) sk.kind = 'charges';
      }
    }, { priority: -10 });
  }

  // ---- 恶魔形态 (the battle half, owner 2026-10-12, §29.23; retargeted on the owner's report of 2026-10-13, §29.32):
  // every own operator CARRYING 恶魔之契 gains +atkPctPerSec every second for the whole battle, stacking with no cap (the
  // 击倒馈赠 additive-stack pattern). It used to draw ONE random own operator at battle start, which the owner could not
  // steer; the equipment is the choice, exactly as 幽魂形态's 幽魂 is. No carrier on the field ⇒ no growth at all: the
  // card is the player's to aim (a carrier that is knocked out pauses it until it redeploys — the old `alive` guard,
  // kept). Dead carriers keep the stacks they earned (`persist` / `allowDead`).
  for (const pid of ownersOf('hex_demonform')) {
    const spec = specOf(pid, 'hex_demonform', 'demonForm');
    const per = isPos(spec.atkPctPerSec) ? spec.atkPctPerSec : 10;
    battle.every(1, () => {
      for (const u of opsOf(pid)) {
        if (!u.alive || !carries(battle, u, DEMON_PACT_ITEM_KEY)) continue;
        battle.addBuff(u, {
          key: 'hex:demonform', refresh: 'stack', stacks: 1, maxStacks: 100000,
          mods: { atkPct: pct(per) }, persist: true, allowDead: true, visible: true, tags: ['hex'],
        });
      }
    });
  }

  // ---- 群蛇形态 (owner 2026-10-12, §29.23): the match spends the banked enemy-points into this ref's
  // `serpentKills.count` when the battle is built; here they are cashed in — that many enemies die the moment they
  // arrive, so they never walk a tile. The earliest spawns go first; a boss or a part is skipped [ASSUMED: the card
  // means wave enemies, and one point must not delete the Final Assault].
  for (const pid of ownersOf('hex_serpentform')) {
    let left = Math.max(0, Math.trunc(Number(specOf(pid, 'hex_serpentform', 'serpentKills').count) || 0));
    if (!(left > 0)) continue;
    const killOne = (e) => {
      if (!(left > 0) || !e || !e.alive || e.side !== 'enemy' || e.tag === 'boss' || e.tag === 'part' || e.isBoss) return false;
      left--;
      battle.kill(e, null);
      return true;
    };
    for (const e of battle.enemies.slice()) killOne(e);
    battle.on('enemySpawn', ({ enemy }) => { killOne(enemy); });
  }

  // ---- 盟约裂变: the two bonds the cap keeps gain ×mul layers, prep side and battle side alike ----
  for (const pid of ownersOf('hex_bondfission')) {
    const mul = Number(specOf(pid, 'hex_bondfission', 'bondFission').mul);
    if (!(mul > 1)) continue;
    battle.on('layerGain', (ctx) => {
      if (!ctx || ctx.playerId !== pid || !(ctx.n > 0)) return;
      if (fissionBonds(battle, pid).has(ctx.bondId)) ctx.n = Math.floor(ctx.n * mul);
    });
  }

  // ---- 背水一战 (the battle half, §29.34): while the window is OPEN, every bond layer gain of this player is ×layerMul.
  // The sim has no LP, so the match stamps `lastDitch.active` into the ref when the battle is built
  // (`onBattleStart.lastDitchArm`); the prep half reads the LP live through the same spec
  // (server/match/hextech.js `layerGainMulOf`). No `active` ⇒ nothing, which is also what an older saved ref gets.
  for (const pid of ownersOf('hex_lastditch')) {
    const spec = specOf(pid, 'hex_lastditch', 'lastDitch');
    if (spec.active !== true) continue;
    const mul = Number(spec.layerMul) > 1 ? Math.trunc(Number(spec.layerMul)) : 2;
    battle.on('layerGain', (ctx) => {
      if (!ctx || ctx.playerId !== pid || !(ctx.n > 0)) return;
      ctx.n = Math.floor(ctx.n * mul);
    });
  }

  // ---- 精准穿透: a battleStart grant (priority -10: after every bond / garrison passive) ----
  const pen = ownersOf('hex_precisionpen');
  if (pen.length) {
    const penSpecs = new Map(pen.map((pid) => [pid, specOf(pid, 'hex_precisionpen', 'precisionPen')]));
    const applyPen = (pid) => {
      const s = penSpecs.get(pid);
      const per = Number(s.perLayers) > 0 ? Number(s.perLayers) : 10;
      const ratio = pct(Number(s.pct) > 0 ? Number(s.pct) : 2);
      const layers = bondLayers(battle, pid, 'preciShip');
      const value = Math.floor(layers / per) * ratio;
      for (const u of opsOf(pid)) {
        const affected = isMember(battle, u, 'preciShip') || (u.def && u.def.position === 'RANGED');
        if (affected && value > 0) passiveBuff(battle, u, 'hex:precisionpen', { defIgnorePct: value, resIgnorePct: value });
      }
    };
    battle.on('battleStart', () => { for (const pid of penSpecs.keys()) applyPen(pid); }, { priority: -10 });
    // the penetration follows the 精准 layers a battle gains (a skill / kill 特质 of the bond keeps feeding it)
    for (const pid of penSpecs.keys()) battle.on('layerGain', (ctx) => { if (ctx && ctx.playerId === pid && ctx.bondId === 'preciShip') applyPen(pid); });
  }

  // ---- 北境长城: the rightmost own column starts with a `shieldPct`% max-HP shield that then grows `stepPct`% of max
  // HP a second up to `capPct`% (owner 2026-10-12; before that it was a flat 100% at battle start). The growth
  // mutates the buff's own `shield` field — the long-standing engine idiom for a numeric 屏障 (op-judge's barrier,
  // 多萝西's cat shield): `u.s.shield` sums the buffs, and damage.js absorbShields spends the buff in place.
  const walls = ownersOf('hex_northwall');
  if (walls.length) {
    const wallSpecs = new Map(walls.map((pid) => [pid, specOf(pid, 'hex_northwall', 'northWall')]));
    /** @type {{unit: any, buff: any, step: number, cap: number}[]} */
    const growth = [];
    battle.on('battleStart', () => {
      for (const pid of wallSpecs.keys()) {
        const s = wallSpecs.get(pid);
        const startPct = Number(s.shieldPct) > 0 ? Number(s.shieldPct) : 50;
        const stepPct = Number(s.stepPct) > 0 ? Number(s.stepPct) : 5;
        const capPct = Number(s.capPct) > 0 ? Number(s.capPct) : 100;
        const ops = opsOf(pid);
        let rightCol = -Infinity;
        for (const u of ops) rightCol = Math.max(rightCol, u.homeC);
        if (!Number.isFinite(rightCol)) continue;
        for (const u of ops) {
          if (u.homeC !== rightCol) continue;
          const buff = battle.addBuff(u, { key: 'hex:northwall', shield: u.s.maxHp * pct(startPct), persist: true, allowDead: true, visible: true });
          growth.push({ unit: u, buff, step: u.s.maxHp * pct(stepPct), cap: u.s.maxHp * pct(capPct) });
        }
      }
    }, { priority: -10 });
    battle.every(1, () => {
      for (const g of growth) {
        if (!g.buff || !(g.unit.s.maxHp > 0) || !(g.cap > 0)) continue;
        if (g.buff.shield >= g.cap - 1e-9) continue;
        g.buff.shield = Math.min(g.cap, (g.buff.shield || 0) + g.step);
        g.unit.markDirty();
      }
    });
  }

  // ---- fourth batch (owner's review of 2026-10-09) ---------------------------------------------------
  // 浴血: every `stepPct`% of max HP lost adds `def` DEF (a stacking buff, at most `max` stacks). The step is derived
  // from the unit's CURRENT missing-HP ratio on every hit, so it also fires on a big single hit and never overshoots.
  for (const pid of ownersOf('hex_holdline')) {
    const s = specOf(pid, 'hex_holdline', 'holdLine');
    const stepPct = Number(s.stepPct) > 0 ? Number(s.stepPct) : 25;
    const def = Number(s.def) || 0;
    const max = Number.isInteger(s.max) && s.max > 0 ? s.max : 4;
    if (!(def > 0)) continue;
    battle.on('damaged', ({ target }) => {
      if (!target || target.kind !== 'op' || target.side !== 'ally' || target.ownerId !== pid) return;
      if (!(target.s.maxHp > 0)) return;
      const lostPct = Math.max(0, 1 - target.hp / target.s.maxHp) * 100;
      const want = Math.min(max, Math.floor(lostPct / stepPct));
      if (want <= 0) return;
      const cur = target.findBuff('hex:holdline');
      const have = cur ? cur.stacks : 0;
      if (want <= have) return;
      battle.addBuff(target, {
        key: 'hex:holdline', refresh: 'stack', stacks: want - have, maxStacks: max,
        mods: { defFlat: def }, persist: true, allowDead: true, visible: true, tags: ['hex'],
      });
    });
  }

  // 火力延伸: the named profession's operators get +`extend` attack range (a persistent passive). rangeExtend is a
  // permanent part of the unit's range (buffs.js permRangeExtend), so `Battle._refreshRange` picks it up at deploy.
  for (const pid of ownersOf('hex_firingline')) {
    const s = specOf(pid, 'hex_firingline', 'rangedExtend');
    const profession = typeof s.profession === 'string' ? s.profession : 'SNIPER';
    const extend = Number(s.extend) > 0 ? Math.trunc(Number(s.extend)) : 1;
    battle.on('battleStart', () => {
      for (const u of opsOf(pid)) if (u.def && u.def.profession === profession) passiveBuff(battle, u, 'hex:firingline', { rangeExtend: extend });
    }, { priority: -10 });
  }

  // 先驱: for the first `seconds` the owning operators cannot drop below 1 HP (the 不屈余烬 pattern: a `fatal` hook that
  // cancels the blow; damage.js then floors the HP at 1, so the unit stays on its feet).
  for (const pid of ownersOf('hex_laststand')) {
    const s = specOf(pid, 'hex_laststand', 'lastStand');
    const seconds = Number(s.seconds) > 0 ? Number(s.seconds) : 30;
    battle.on('fatal', (c) => {
      if (c.prevented || !c.unit || c.unit.kind !== 'op' || c.unit.side !== 'ally' || c.unit.ownerId !== pid) return;
      if (battle.time < seconds) c.prevented = true;
    }, { priority: -99 });
  }

  // 超载协议: opening a skill costs the caster `selfDmgPct`% of its max HP as 失去生命 (not 受到伤害: no 受击回复 SP, no
  // shield, not counted as damage taken) — the trade-off of the SP-cost cut carried by `battle.spCostFlat`.
  for (const pid of ownersOf('hex_overdrive')) {
    const s = specOf(pid, 'hex_overdrive', 'overdrive');
    const dmgPct = Number(s.selfDmgPct) > 0 ? Number(s.selfDmgPct) : 4;
    battle.on('skillStart', ({ unit }) => {
      if (!unit || unit.kind !== 'op' || unit.side !== 'ally' || unit.ownerId !== pid) return;
      if (!(unit.s.maxHp > 0)) return;
      const amount = unit.s.maxHp * (dmgPct / 100);
      if (!(amount > 0)) return;
      // never lethal: the card's cost is a drain, not a suicide (floor at 1 like ctx.spendLp)
      const room = Math.max(0, unit.hp - 1);
      if (room > 0) battle.loseHp(unit, Math.min(amount, room), { source: null, sourceless: true, tags: ['hex', 'overdrive'] });
    });
  }

  // 战地医院: every knock-out heals the lowest-HP-ratio own operator by `healPct`% of its max HP (already-mitigated
  // amount: `battle.heal` applies the target's healing multipliers). Deliberately useless on a leader fight (few kills).
  for (const pid of ownersOf('hex_fieldhospital')) {
    const s = specOf(pid, 'hex_fieldhospital', 'fieldHospital');
    const healPct = Number(s.healPct) > 0 ? Number(s.healPct) : 10;
    battle.on('kill', ({ killer, victim }) => {
      if (!victim || victim.side !== 'enemy') return;
      if (!killer || killer.side !== 'ally' || killer.ownerId !== pid) return;
      let best = null;
      for (const u of opsOf(pid)) {
        if (!u.alive || !(u.s.maxHp > 0)) continue;
        const ratio = u.hp / u.s.maxHp;
        if (!best || ratio < best.ratio) best = { u, ratio };
      }
      if (!best || best.ratio >= 1) return;
      const amount = best.u.s.maxHp * (healPct / 100);
      if (amount > 0) battle.heal(null, best.u, amount, { silent: false });
    });
  }

  // 损伤加强: enemies take `elemTakenMul`× ELEMENT GAUGE damage (damage.js elementIntake) — it makes their element bursts
  // come faster, it does NOT scale HP damage. Applied at spawn so it also reaches escorts and mid-fight summons.
  for (const pid of ownersOf('hex_lossamp')) {
    const s = specOf(pid, 'hex_lossamp', 'elemAmp');
    const mul = Number(s.elemTakenMul);
    if (!(mul > 1)) continue;
    battle.on('enemySpawn', ({ enemy }) => {
      if (!enemy || !enemy.alive) return;
      passiveBuff(battle, enemy, 'hex:lossamp', { elemTakenMul: mul });
    });
  }
  // 损伤加强's second half (the owner's list of 2026-10-13, §29.32): every second, every enemy ON THE FIELD takes
  // `erosionPerSec` erosion (侵蚀) element damage. Owner's words: 「额外加上每秒场上敌人受到100点侵蚀损伤；分不分身都听你的。」
  //   * 「分身」: every body on the field is one enemy and burns on its own — a 回响 split child, a mid-fight summon and
  //     an escort alike (they are `battle.enemies` with `alive && deployed`). Nothing here reads a parent id, so the
  //     question does not arise mechanically; the choice is written down rather than left implicit.
  //   * `ignoreSelect: true`: an aura over the field, not a selection — a 隐匿 or 无法选中 enemy still burns (it IS an
  //     enemy on the field), and the same shape lets the instance reach a 起飞 ally none of this touches.
  //   * ONE scheduler for the field, with the STRONGEST owner's number: this card's own enemy debuff lives under a single
  //     buff key (`hex:lossamp`, replaced, never stacked), so two owners do not stack it either.
  //   * The gauge multiplier above applies to this tick like to any other element damage (it is the same `elementIntake`
  //     path), which is what makes the two halves one card: 100 × 1.5 = 150 gauge a second.
  {
    let dot = 0;
    for (const pid of ownersOf('hex_lossamp')) {
      const v = Number(specOf(pid, 'hex_lossamp', 'elemAmp').erosionPerSec);
      if (Number.isFinite(v) && v > dot) dot = v;
    }
    if (dot > 0) {
      battle.every(1, () => {
        for (const e of battle.enemies) {
          if (!e || !e.alive || !e.deployed) continue;
          battle.dealDamage(null, e, { type: 'element', element: 'erosion', amount: dot, ignoreSelect: true, tags: ['hex', 'lossamp'] });
        }
      });
    }
  }
}

/**
 * Dispatch the fifth batch's four scripts (the owner's review of 2026-10-11). Each module lives in its own file under
 * `hexcards/` with a fixed contract (see its header), and every one of them is handed the SAME hook bundle built by
 * `hexHooks(battle)` — so the four can never read the player's owned hexes through four slightly different rules, and a
 * test can drive one module in isolation by building the same bundle over its harness battle.
 *
 * Registered here rather than inside each module so the install order stays visible in one place: the two damage-side
 * scripts (反击装甲's riposte, 盾墙's split) both answer `damaged` / `hit`, 盾墙 at priority -20 (the 坚守 slot: cut
 * first, split what is left) and 反击装甲 at the default priority, so the split's instances are already dealt when the
 * riposte answers them. 精锐训练 and 战争机器 only grant battleStart passives at priority -10 (after every bond and
 * garrison passive, the house slot).
 *
 * Every module returns a count and is a no-op when its card is absent, so nothing here costs a field that owns none.
 *
 * **The card's script key is the switch, and it is checked here.** A module must only run for a player whose OWN card
 * record actually carries its key (`drill` / `armor` / `shieldwall` / `warmachine`). Without this gate a module falls back
 * to its documented defaults and fires anyway — measured against the pre-2026-10-11 data set (which carries no script key
 * at all): 精锐训练 still granted the per-round ATK, 反击装甲 still riposted and 战争机器 still gave the 联防 aura. That
 * is behaviour invented by code rather than read from the data, and it silently moved the golden corpus. Gating at the
 * single injection point keeps each module's own "absent card → no-op" reasoning true for BOTH kinds of absence: no ref,
 * and a ref whose record predates the key.
 */
/**
 * hex id → the script key its record must carry for the module to run. Module-scope and exported so the content test can
 * pin every wired id: a typo in this map is a SILENT no-op (the module gates on a key no record carries), which is
 * exactly the kind of failure the batch-13 tests exist to catch.
 */
export const HEX_SCRIPT_KEYS = Object.freeze({
    hex_drill: 'drill', hex_armor: 'armor', hex_shieldwall: 'shieldwall', hex_warmachine: 'warmachine',
    // sixth batch (the owner's list of 2026-10-11)
    hex_humanrite: 'humanRite', hex_rangedist: 'rangedist', hex_minefield: 'minefield', hex_breaker: 'breaker',
    hex_neurotoxin: 'neurotoxin', hex_ricochet: 'ricochet',
    // tenth batch (the owner's list of 2026-10-12, §29.27)
    hex_logos: 'logos', hex_onebody: 'oneBody',
    // tenth batch (the owner's list of 2026-10-15): the batch10.js scripts
    hex_blockwall: 'blockwall', hex_sharepain: 'sharePain', hex_terramourn: 'deathBlast',
    hex_directive: 'directiveAtk', hex_directive2: 'directiveType',
    hex_rabbithead: 'rabbitHead', hex_profresonance: 'profResonance',
    // thirteenth batch (业主 2026-10-19)
    hex_untouchable: 'untouchable', hex_pearlglove: 'pearlglove', hex_physarts: 'physarts',
    hex_quantum: 'quantum', hex_tapdance: 'tapdance', hex_ultrefresh: 'ultrefresh',
    hex_omenpact: 'omenpact', hex_proteinshake: 'proteinshake', hex_frostghost: 'frostghost',
    hex_heavyhitter: 'heavyhitter',
    // fourteenth batch (业主 2026-10-19)
    hex_canlight: 'canlight', hex_glasscannon: 'glasscannon', hex_heavyload: 'heavyload',
    hex_umbrellabreak: 'umbrellabreak', hex_warding: 'warding', hex_voidreturn: 'voidreturn',
    hex_corpsehill: 'corpsehill', hex_oldpower: 'oldpower',
});

function installHexCards(battle) {
  const h = hexHooks(battle);
  const SCRIPT_KEY = HEX_SCRIPT_KEYS;
  /** The `params` of a player's own ref for `hexId`. */
  const paramsOf = (pid, hexId) => {
    const ps = battle.getPlayer ? battle.getPlayer(pid) : null;
    const ref = ((ps && ps.playerEffects) || []).find((e) => e && (e.data?.hexId === hexId || e.key === `${HEX_KEY}${hexId}`));
    return ref && ref.params && typeof ref.params === 'object' ? ref.params : null;
  };
  // One gate for all four modules: `ownersOf` is the single way each of them decides whether its card is on the field
  // (each reads it once at install), so narrowing that reader is enough — and it keeps the four from drifting apart.
  const gated = {
    ...h,
    ownersOf: (hexId) => {
      const key = SCRIPT_KEY[hexId];
      const owners = h.ownersOf(hexId);
      if (!key) return owners;
      return owners.filter((pid) => {
        const params = paramsOf(pid, hexId);
        return !!params && params[key] !== undefined && params[key] !== null;
      });
    },
  };
  installDrill(gated);
  installArmor(gated);
  installShieldwall(gated);
  installWarmachine(gated);
  // sixth batch (the owner's list of 2026-10-11) — same bundle, same gate
  installHumanRite(gated);
  installRangeDist(gated);
  installMinefield(gated);
  installBreaker(gated);
  installNeurotoxin(gated);
  installRicochet(gated);
  // tenth batch (the owner's list of 2026-10-12, §29.27) — same bundle, same gate
  installLogos(gated);
  installOneBody(gated);
  // tenth batch (the owner's list of 2026-10-15) — the same bundle, the same gate
  installBlockwall(gated);
  installSharePain(gated);
  installTerraMourn(gated);
  installDirectiveAtk(gated);
  installDirectiveType(gated);
  installRabbitHead(gated);
  installProfResonance(gated);
  // thirteenth batch (业主 2026-10-19): batch14b.js's five (batch14a.js's five are wired with them once it lands)
  installTapdance(gated);
  installUltrefresh(gated);
  installOmenpact(gated);
  installProteinShake(gated);
  installHeavyHitter(gated);
  installUntouchable(gated);
  installPearlGlove(gated);
  installPhysArts(gated);
  installQuantum(gated);
  installFrostGhost(gated);
  // fourteenth batch (业主 2026-10-19) — same bundle, same gate
  installCanlight(gated);
  installGlassCannon(gated);
  installHeavyLoad(gated);
  installUmbrellaBreak(gated);
  installWarding(gated);
  installVoidReturn(gated);
  installCorpseHill(gated);
  installOldPower(gated);
}

/**
 * The bonds a 盟约裂变 player keeps active: the `cap` active ones with the most layers (ties → data order), the rule
 * `server/match/bondsMeta.js computeBonds` applies to the prep-side state. ONE implementation lives in
 * shared/hextech.js (it is the only way the two readers can be kept from drifting); the battle's data order is passed in
 * so a tie resolves exactly as it does in prep. Returns an empty set when the hex is absent.
 */
function fissionBonds(battle, pid) {
  const ps = battle.getPlayer(pid);
  const cap = Number(hexCapOf(ps)) > 0 ? Number(hexCapOf(ps)) : 2;
  const order = Object.values(gameData().bonds || {}).map((b) => b && b.bondId).filter(Boolean);
  return sharedFissionBondIds(ps && ps.bonds, cap, order);
}

/** The active-bond cap a player's own hexes ask for (`bondFission.cap`), 0 when none does. */
export function hexCapOf(playerInput) {
  for (const ref of (playerInput && playerInput.playerEffects) || []) {
    const cap = fissionCap(ref && ref.params && ref.params.bondFission);
    if (cap > 0) return cap;
  }
  return 0;
}

// ---- enemy verbs (DESIGN §29.10) -----------------------------------------------------------------------------------
//
// Until the fourth batch an enemy hex could only carry `mods` (the seven wave numbers), so every enemy card read as
// "a bit more HP / ATK / speed". A **verb** card names a script here instead. The ids arrive on `flags.enemyHexIds`
// (server/match/match/combat.js newBattle — one site, so normal / boss / 联防 / rehearsal / preview all get them), and
// the record is read back out of data/hextech.json for its `params`.
//
// Every number here comes from the card's `params` with a documented default, so a hand-tuned roster needs no code
// change. Determinism: anything random uses `battle.rng` (never Math.random / the clock) — the client re-simulates
// from the same spec and SP_VERIFY compares the digests.

/** The enemy hex record of an id, or null. `source` is the optional battle-side fallback hexData() understands. */
function enemyHexRecord(id, source = null) {
  const d = hexData(source);
  const list = d && d.enemyHexes ? d.enemyHexes : null;
  return list && list[id] ? list[id] : null;
}

/** A positive number from `params` (or the default). */
const pnum = (v, d) => (typeof v === 'number' && Number.isFinite(v) && v > 0 ? v : d);

/**
 * Install the battle scripts of every enemy verb card the enemy side owns. Idempotent per battle (a field is built
 * once, but the guard keeps a double install from stacking handlers).
 */
function installEnemyVerbs(battle) {
  const ids = battle.flags && Array.isArray(battle.flags.enemyHexIds) ? battle.flags.enemyHexIds : null;
  if (!ids || !ids.length) return;
  if (battle._enemyVerbsInstalled) return;
  battle._enemyVerbsInstalled = true;
  // The records come from THIS battle's own data when the global view has none (hexData's `source` fallback): on a page
  // the loader fed without `hextech`, `gameData()` is the empty `{}` and every lookup used to return null — the verbs
  // were then skipped in silence while the server ran them (user report 2026-10-11). A battle that carries the roster
  // still resolves it, and a battle that does not now reports the miss instead of pretending the cards are absent.
  const source = battle.ds || battle.data || null;
  for (const id of ids) {
    const rec = enemyHexRecord(id, source);
    if (!rec || typeof rec.verb !== 'string') {
      if (!rec) battle._handlerError?.('enemyHex:missing', null, new Error(`no data/hextech.json record for ${id} (the roster did not reach this battle)`));
      continue;
    }
    const fn = ENEMY_VERB_SCRIPTS[rec.verb];
    if (!fn) continue; // an unknown verb is a build error (tools/build-hextech.mjs); never throw mid-battle
    const params = rec.params && typeof rec.params === 'object' ? rec.params : {};
    try { fn(battle, params, id); } catch (e) { battle._handlerError?.(`enemyHex:${id}`, null, e); }
  }
}

/** The operators (and tokens) of one ally that a verb may heal / buff. */
const alliesOf = (battle) => battle.allies();

/**
 * Per-unit throttle key of 铁壁 (the mirror of 坚守盟约's `STEAD_CD`, bonds/addon/battle.js). The reflected instance is
 * marked `steadThorn`, but that alone cannot break a cross-unit cycle — a counter-attack from the ally side starts a new
 * one every time — so the enemy also refuses to reflect more than once per cooldown. See the script's comment.
 */
const THORN_CD = 'hex:ironwall:cd';

/**
 * One script per verb id in shared/hextech.js `ENEMY_VERBS`. Each receives the battle, the record's `params` and the id.
 * Helpers are imported from content/enemies/helpers.js — the same ones the official enemy kits use, so selection rules
 * (areaSelectable, 隐匿, 无法选择) behave exactly as they do for a built-in enemy.
 */
const ENEMY_VERB_SCRIPTS = Object.freeze({
  /**
   * 亡语: on a KNOCK-OUT, arts damage to the allies around the corpse.
   *
   * `reason === 'killed'` is the gate every built-in death kit uses (enemies/archetypes.js `death`, enemies/times.js):
   * `Battle._remove` fires `death` for a leak, an expiry and a retreat as well, and the card says 被击倒 — an enemy that
   * reached the goal escaped, it did not blow up. Without the gate a leaked enemy damaged the operators it walked past.
   */
  deathrattle(battle, p) {
    const ratio = pnum(p.ratio, 1.2);
    const radius = pnum(p.radius, 1);
    const shape = p.shape === 'box' ? 'box' : 'plus';
    battle.on('death', ({ unit, reason }) => {
      if (reason !== 'killed') return;
      if (!unit || unit.side !== 'enemy' || !(unit.s.atk > 0)) return;
      const hit = areaAlliesInTiles(battle, unit, Math.round(unit.y), Math.round(unit.x), shape, radius);
      for (const a of hit) hurt(battle, unit, a, unit.s.atk * ratio, 'arts', { tags: ['hexVerb'] });
    });
  },

  /** 破甲弹: a physical hit shreds the struck ally's DEF, stacking for the battle. */
  armorbreak(battle, p) {
    const flat = pnum(p.flat, 25);
    const max = Number.isInteger(p.max) && p.max > 0 ? p.max : 8;
    battle.on('hit', ({ source, target, dmg }) => {
      if (!source || source.side !== 'enemy' || !target || target.side !== 'ally') return;
      if (!dmg || dmg.cancel || dmg.type !== 'phys') return;
      const cur = target.findBuff('hexverb:armorbreak');
      const have = cur ? cur.stacks : 0;
      if (have >= max) return;
      battle.addBuff(target, {
        key: 'hexverb:armorbreak', refresh: 'stack', stacks: 1, maxStacks: max,
        mods: { defFlat: -flat }, duration: Infinity, persist: true, visible: true, tags: ['hexVerb'],
      });
    });
  },

  /** 淬毒: the enemy's attacks carry erosion element damage. */
  venom(battle, p) {
    const ratio = pnum(p.ratio, 0.08);
    battle.on('hit', ({ source, target, dmg }) => {
      if (!source || source.side !== 'enemy' || !target || target.side !== 'ally') return;
      if (!dmg || dmg.cancel || !dmg.isAttack) return;
      if (dmg.tags && dmg.tags.includes('hexVerb')) return; // never chain off our own element application
      if (!(source.s.atk > 0)) return;
      elem(battle, source, target, p.element || 'erosion', source.s.atk * ratio, { tags: ['hexVerb'] });
    });
  },

  /**
   * 铁壁: reflects a share of the ENEMY'S OWN ATK back at whoever hits it physically.
   *
   * The amount is `target.s.atk × ratio` — a share of the MONSTER's attack power (the owner's rebalance of 2026-10-14,
   * §29.39), NOT a share of the damage it just took. It used to be `c.amount × 15 %` (the post-mitigation damage the
   * enemy had just received), which made the card scale with the PLAYER's own damage: the harder the operator hit, the
   * harder the reflect — and a high-DEF operator took a fraction of a fraction (§29.15 measured 15 % → 0.75 %). Reading
   * the enemy's ATK instead decouples the two: the reflect is the same whatever the operator's damage or DEF, it scales
   * with the enemy the card is attached to, and an ATK buff that enemy gained (军旗, a leader's own scaling) is included
   * because `t.s` is read live at fire time. An enemy with ATK 0 (a support / 器物 carrier) reflects nothing at all.
   *
   * The recursion guard is a THROTTLE, not just an instance marker. Marking the reflected instance (`steadThorn`, as
   * 坚守盟约 does) only stops this handler from reflecting its own blow; it cannot stop the cycle that actually runs
   * away: enemy hits ally → an ally-side counter/reflect (反击装甲, a thorns bond) hits the enemy → this handler reflects
   * → the ally is hit → the counter fires again … Bounded only by the engine's hook-depth limit (32), which aborts the
   * chain and logs a `hookDepth` error (measured: `coop2-ABYSS-10-boosted` went from 0 to 2 sim errors). 坚守盟约 hits
   * the same wall and solves it with a per-unit cooldown (`STEAD_CD`, bonds/addon/battle.js), so this uses one too: a
   * given enemy reflects at most once per `THORN_CD`.
   *
   * `defIgnorePct: 1` — the reflect is a flat share of the enemy's ATK, so it must not be mitigated a second time by the
   * attacker's own DEF. The old formula hit exactly that trap: a `phys` instance of `amount = c.amount × ratio` went
   * through `mitigate` against the operator's DEF again, and since a median operator's DEF (180–500) exceeded 15 % of a
   * normal hit the delivered damage collapsed onto the `MIN_DAMAGE_RATIO` floor — measured on a DEF-200 operator,
   * 1000-damage hits reflected 7.5 each instead of 150, i.e. **0.75 % of the damage dealt instead of 15 %** (§29.15).
   * Keeping the type `phys` (rather than dealing `true` damage) preserves 庇护 and physical barriers, so the change
   * moves only the amount.
   */
  ironwall(battle, p) {
    // 业主 2026-10-16：反弹比例从 20% 改成 **10%**（数据 data/hextech.json 的 params.ratio 也同步改）。
    const ratio = pnum(p.ratio, 0.1);
    const cd = pnum(p.cooldown, 0.2);
    battle.on('damaged', (c) => {
      const t = c && c.target;
      if (!t || t.side !== 'enemy' || !t.alive) return;
      const dmg = c.dmg;
      if (!dmg || dmg.cancel || dmg.steadThorn || dmg.type !== 'phys') return;
      if (dmg.tags && (dmg.tags.includes('hpLoss') || dmg.tags.includes('hexVerb'))) return;
      const src = c.source;
      if (!src || !src.alive || src.side !== 'ally') return;
      const last = t.mem && t.mem[THORN_CD] != null ? t.mem[THORN_CD] : -Infinity;
      if (battle.time - last < cd - 1e-9) return;
      const atk = t.s && Number.isFinite(t.s.atk) ? t.s.atk : 0;
      const back = atk * ratio;
      if (!(back > 0)) return;
      if (t.mem) t.mem[THORN_CD] = battle.time;
      const info = battle.makeDamage({ amount: back, type: 'phys', isSkill: true, defIgnorePct: 1, tags: ['hexVerb'] });
      info.steadThorn = true;
      battle.dealDamage(t, src, info);
    });
  },

  /**
   * 腐蚀领域: a ground zone under a random ally every `period` s; it detonates after `fuse` s for true damage.
   *
   * The damage scales with the round being fought (owner's spec, 2026-10-12): `damage + damagePerRound * x`, where
   * `x = battle.round` — 80 + 40x with the roster's numbers until 2026-10-14, when the owner dropped the slope to
   * **80 + 25x** (the roster's `damagePerRound` is the single source; the code below only reads it). `x` is read once per
   * detonation from `battle.round`, which the match fixes for the whole battle (`Battle.round`, set by `newBattle`); a
   * bare harness battle has `round` 0 / missing, and then only the flat part applies — never a throw (the same rule
   * 精锐训练's per-round half follows, hexcards/drill.js). Uncapped: R11 = 355, R14 = 430.
   *
   * 干员 ONLY (owner's report of 2026-10-13, §29.32): the card's own text is 「对范围内我方干员造成…真实伤害」, but both
   * halves used `battle.allies()` / `alliesInRadius`, which include every TOKEN — so it planted a zone under 多萝西's
   * mines or 望's 棋子 and blew them up (and a damaged trap then soaked the team's heals, the second half of the same
   * report). Placement and blast now both require `kind === 'op'`, which is what the text says; a field holding no
   * operator plants no zone at all.
   */
  corrode(battle, p) {
    const period = pnum(p.period, 4);
    const fuse = pnum(p.fuse, 2);
    const radius = pnum(p.radius, 1.5);
    const base = pnum(p.damage, 80);
    const perRound = pnum(p.damagePerRound, 40);
    battle.every(period, () => {
      const list = alliesOf(battle).filter((a) => a.alive && a.kind === 'op');
      if (!list.length) return;
      const a = list[Math.min(list.length - 1, Math.floor(battle.rng() * list.length))];
      const x = a.x, y = a.y;
      battle.fx('zone', { x, y, r: radius, dur: fuse, kind: 'hexcorrode' });
      battle.after(fuse, () => {
        // x = the round being fought; 0 / missing / NaN → the flat part alone (a bare harness battle is the normal case)
        const round = Number(battle.round);
        const rx = Number.isFinite(round) && round > 0 ? round : 0;
        const dmg = base + perRound * rx;
        for (const t of battle.alliesInRadius(x, y, radius)) {
          if (t && t.alive && t.kind === 'op') hurt(battle, null, t, dmg, 'true', { ignoreSelect: true, tags: ['hexVerb'] });
        }
        battle.fx('explode', { x, y, r: radius });
      });
    });
  },

  /** 嗜血: heals a share of the damage it deals. */
  bloodthirst(battle, p) {
    const ratio = pnum(p.ratio, 0.4);
    battle.on('damaged', (c) => {
      const src = c && c.source;
      if (!src || src.side !== 'enemy' || !src.alive) return;
      if (!c.amount || c.amount <= 0) return;
      if (c.dmg && c.dmg.tags && c.dmg.tags.includes('hexVerb')) return;
      battle.heal(src, src, c.amount * ratio);
    });
  },

  /** 狂化: under half HP it gains attack speed (a persistent buff, so it applies once). */
  frenzy(battle, p) {
    const threshold = pnum(p.thresholdPct, 50) / 100;
    const aspd = pnum(p.aspd, 70);
    const key = 'hexverb:frenzy';
    battle.on('damaged', ({ target }) => {
      if (!target || target.side !== 'enemy' || !target.alive) return;
      if (!(target.s.maxHp > 0) || target.hp / target.s.maxHp >= threshold) return;
      if (target.findBuff(key)) return;
      passiveBuff(battle, target, key, { aspd });
    });
  },

  /**
   * 隐匿: opens in stealth (lifted by a block, restored a few seconds after it ends — the built-in `stealth` kit).
   *
   * Owner's spec (2026-10-12): only GROUND, non-boss enemies open hidden. A flyer (or a hovering / levitated enemy —
   * `Unit.isFlying`) has no block to end its stealth and no ground path to hide along, and a boss opening hidden would
   * hide the stage's main threat behind an untargetable frame; both would read as a bug rather than as pressure, so the
   * gate mirrors the one 回响 uses below (`tag === 'boss'`, plus the `isBoss` spawn flag `battle/spawns.js` sets for the
   * same tag) plus the airborne test.
   *
   * Owner's follow-up (2026-10-12): a 次数怪 (a 频次 / hit-count unit — `isHitCount`, the `ab:hitCount` /
   * `ab:hitCountArts` buff kitTimes and the leaders' hit-count summons set) never opens hidden either. Its only reveal
   * line is 被阻挡, and the 器物 are 无法被阻挡 (`kitTimes` = `times` + `unblockable`), so the two together left such an
   * enemy permanently unselectable: measured on 磨砻 (`enemy_1195_sfyin`, death ⇒ 2 木制瑞印) with this card, both
   * children carried `ab:stealth`, `enemyStealthed` was true, `canTargetEnemy` was false, and they walked into the goal
   * untouched — no operator could ever knock one out. The gate is scoped to THIS card: the official kits' own 隐匿
   * (逐火's 余烬, 再生's 傀儡 …) keeps hiding, because those kits read `enemyStealthed`, not this handler.
   *
   * The 频次 flag is already on the unit when this runs: the kit dispatcher is registered at priority 100
   * (`content/enemies.js ensureInstalled`), ahead of this handler's default 0, so `isHitCount` is decided for a
   * death-spawned 器物, a leader's summon (余音 / 刺胄之弹) and a stage-scheduled one alike (probed through the real
   * sim for all three).
   */
  stealth(battle, p) {
    const restore = pnum(p.restore, 3);
    battle.on('enemySpawn', ({ enemy }) => {
      if (!enemy || !enemy.alive || enemy.findBuff('ab:stealth')) return;
      if (enemy.tag === 'boss' || enemy.isBoss || enemy.isFlying) return;
      if (isHitCount(enemy)) return;
      // 业主 2026-10-20「隐匿不应该把不能阻挡的怪隐匿」: the ONLY way this card lifts stealth is 被阻挡, so an enemy the
      // engine refuses to block can never be revealed — it would be untargetable for the whole field. The four flags
      // are exactly the ones `battle/blocking.js _checkBlock` refuses (`unblockable | levitate | fear | sleep`; 无法阻挡
      // / BLOCK_FREE, 浮空, 恐惧, 沉睡). Innate ones are already on the unit here: the kit dispatcher runs at priority
      // 100, ahead of this handler (the same ordering the 次数怪 gate relies on), so `ab:unblockable` / 自缚 / 浮空 from
      // a kit is visible at spawn. Transient fear/levitate still resolve afterwards like any other buff.
      if (cannotBeBlocked(enemy)) return;
      // 中途变形 (owner report 2026-10-15): the airborne test above reads the unit ONCE, at spawn — but
      // `Unit.isFlying` is a live getter over `motion` / `flags.float` / `flags.levitate`, and 守墓石像
      // (enemy_1172_dugago) TAKES OFF mid-battle: its `statue()` kit runs `e.motion = 'FLY'` when the stone form
      // expires (content/enemies/archetypes.js). Such an enemy kept the `ab:stealth` it opened with, so it stayed
      // unselectable for the rest of the field — exactly the "a flyer has no block to end its stealth and no ground
      // path to hide along" case this gate exists for. Re-check a few times a second and drop the buff the moment the
      // unit is airborne. Scoped to THIS card's own buff: an enemy already hiding through its own kit
      // (`kitStealth`) is skipped by the `findBuff` guard right above, so the official kits keep their own rules.
      battle.addBuff(enemy, {
        key: 'ab:stealth', flags: { stealth: true }, persist: true, data: { stealthRestore: restore },
        interval: 0.25,
        onTick: ({ battle: b, unit: u }) => { if (u.isFlying) b.removeBuff(u, 'ab:stealth'); },
      });
    });
  },

  /**
   * 回响: on a KNOCK-OUT splits into `count` weaker copies continuing its route (spawnChildren copies the mods).
   *
   * The `reason === 'killed'` gate is the same one the built-in split kits use (enemies/archetypes.js `death`,
   * enemies/times.js: 'a leak is no death'). `Battle._remove` fires `death` for a leak too, so without it an enemy that
   * reached the goal split in two at the goal — those children then leaked as well, and because a leaked body is
   * `counted` (it costs LP and breaks 完美作战), ONE scheduled enemy billed the leaker three times. A stage whose own
   * enemies all leaked therefore grew without bound: measured 5 leaked enemies → 15 counted leaks, and the 联防 bill
   * (min(cap, counted leaks)) is charged against that inflated number.
   *
   * A content-made NEUTRAL (`mem.noLeak` — 隐德来希's 心烛) is never split. Such a summon is not an enemy of the stage at
   * all: it is placed as a marker that follows its original, `countInTotal: false`, `notCountInTotal`, with its own
   * inline record that is absent from data/enemies.json (`lifePointReduce: 0`, never a leak or an LP cost). Copying it
   * cannot produce a meaningful body: `spawnChildren` re-derives a route from the parent's own, and the 心烛's stay
   * route has `start === end`, so `spawnEnemy` appends the stage's GOAL leg and the copy — resolved through
   * `getEnemy('enemy_5601_entlec')` → the FALLBACK record (2000 HP, speed 1), since the inline def is not passed on —
   * walks off the map and leaks, charging LP and 完美作战 for a summon that is worth neither. Measured: one 心烛 billed
   * 3 counted leaks where the entire summon is worth 0, and the match's honest-result validator then rejected the field
   * ('leak key': `enemy_5601_entlec` is in no spawn schedule).
   *
   * `countInTotal: unit.counted` keeps the parent's own LP reading for the copies that ARE real enemies: without it
   * `spawnChildren` passes nothing and `spawnEnemy` falls back to `counted: true`, so a copy of an uncounted spawn
   * would start costing LP.
   *
   * 器物 / 次数怪 are never split (owner's report of 2026-10-13, §29.33). 木制瑞印 (`enemy_1196_msfyin`, 2 hits) and its
   * 13 siblings (卷轴 / 铜镜 / 镇纸 / 茶器 / 矛头 / 灯盘 …) are the mode's 器物: a hit-count OBJECT, not a body — the
   * card has nothing to halve on it (its "HP" is a hit count) and a copy is a second object the stage never scheduled.
   * The card already made one generation of them unavoidable, because a split's children are ordinary enemies in every
   * other respect: 磨砻 (`enemy_1195_sfyin`, NOT a 器物 — its kit is a plain DeadSpawn) still splits, and each copy's
   * two 木制瑞印 spawn as usual (that first generation is the card's own point). What used to happen is the SECOND
   * generation: the death-spawned 器物 itself was knocked out and split again, so the bodies multiplied without bound —
   * measured on `solo/FUNNY/17`: 12 磨砻 → 77 bodies without the card and **549** with it (36 磨砻 + 216 瑞印 + …); with
   * this gate the seals are a leaf. `isHitCount` is the same predicate 隐匿 uses above (§29.29) and it is already on the
   * unit here: the kit dispatcher runs at priority 100 (`content/enemies.js ensureInstalled`), ahead of this handler.
   */
  echo(battle, p) {
    const count = pnum(p.count, 2);
    const hpRatio = pnum(p.hpRatio, 0.5);
    // 业主 2026-10-16：分裂出来的两个**攻击力减半** —— 比例读数据的 `atkRatio`（缺省 0.5），
    // 这样改数值只动 roster（tools/hextech/roster.mjs）而不用碰 sim。
    const atkRatio = pnum(p.atkRatio, 0.5);
    // Owner's rebalance of 2026-10-13: the split became a CHANCE that grows with the round being fought —
    // `chance = min(1, chanceBase + chancePerRound × x)`, x = `battle.round` (the same per-round reading 腐蚀领域 uses
    // above; a bare harness battle has round 0 / missing and then only the flat part applies). The roster's numbers give
    // 0.1 + 0.1x: 20 % in R1, 60 % in R5, certain from R9 on. `chance` absent / 1 keeps the old always-split behaviour,
    // so a hand-built ref or an old save is unchanged.
    const base = Number.isFinite(Number(p.chance)) ? Number(p.chance) : 1;
    const perRound = Number.isFinite(Number(p.chancePerRound)) ? Number(p.chancePerRound) : 0;
    const chance = () => {
      const round = Number(battle.round);
      const rx = Number.isFinite(round) && round > 0 ? round : 0;
      return Math.max(0, Math.min(1, base + perRound * rx));
    };
    battle.on('death', ({ unit, reason }) => {
      if (reason !== 'killed') return;
      if (!unit || unit.side !== 'enemy' || unit.tag === 'boss') return;
      if (unit.mem && unit.mem.noLeak) return; // a content-made neutral (心烛) is never an enemy of the stage
      if (isHitCount(unit)) return; // a 器物 (木制瑞印 and its kind) is a hit-count object, never a body to split
      if (unit._hexEchoed) return; // a split child may not split again
      unit._hexEchoed = true;      // the roll is spent either way: a failed roll never re-rolls on the same corpse
      if (battle.rng() >= chance()) return;
      const kids = spawnChildren(battle, unit, unit.defId, count, {
        mods: { ...(unit.mods || {}), hpMul: (unit.mods && unit.mods.hpMul) || 1 },
        countInTotal: unit.counted,
      });
      for (const k of kids) {
        k._hexEchoed = true;
        k.hp = Math.max(1, k.s.maxHp * hpRatio);
        // 业主 2026-10-16：分裂出来的两个**攻击力减半**（生命值仍按 hpRatio，见上）。
        // `k.s.atk` 是这一场的生效值（mods / 增益都已折进去），直接对半；基础值按同样比例缩，
        // 免得后续重算把它拉回原样。
        const atk = k.s && Number.isFinite(k.s.atk) ? k.s.atk : null;
        if (atk != null && atkRatio !== 1) {
          k.s.atk = atk * atkRatio;
          if (k.base && Number.isFinite(k.base.atk)) k.base.atk *= atkRatio;
        }
        k.markDirty();
      }
    });
  },

  /** 军旗: every enemy knock-out empowers the survivors (aura-style, re-applied on a short interval). */
  banner(battle, p) {
    const atkPct = pnum(p.atkPct, 2) / 100;
    const max = pnum(p.max, 40) / 100;
    const stacksOf = new Map();
    battle.on('kill', ({ victim }) => {
      if (!victim || victim.side !== 'enemy') return;
      for (const e of battle.enemies) {
        if (!e || !e.alive || e === victim) continue;
        const cur = stacksOf.get(e) || 0;
        if (cur >= max) continue;
        const next = Math.min(max, cur + atkPct);
        stacksOf.set(e, next);
        passiveBuff(battle, e, 'hexverb:banner', { atkPct: next });
      }
    });
  },

  // =================================================================================================================
  // ninth batch (the owner's list of 2026-10-15): the enemy cards. Everything below is the script half of a card
  // whose record lives in tools/hextech/roster.mjs ENEMY_HEXES; the plain multipliers of that batch stay `mods` and
  // need no entry here.
  //
  // Three house rules every script below keeps, because walking into them is silent rather than loud:
  //   * 器物 (a hit-count object: 木制瑞印 and its siblings) is not a body — it neither heals, is healed, nor counts
  //     as 'an enemy' for a spawn-wide card (`isHitCount`, the gate 回响 / 隐匿 already use);
  //   * a boss is exempt wherever the card's own text says so (无头苍蝇's 恐惧): the stage's leader is the one unit a
  //     player cannot route around, so a card that disables it outright would delete the round's fight;
  //   * our own damage carries the `hexVerb` tag, so a card can never answer its own output (the loop 铁壁's comment
  //     describes: a handler that reacts to damage must recognise its own instance).
  // =================================================================================================================

  /**
   * 莱茵护甲: every enemy opens with a 次数盾 — a shield that absorbs a fixed number of HITS rather than HP.
   *
   * **这个盾是"额外一层"，不是"血量等于次数"** —— 这正是引擎自己的 `ab.hitShield`（enemies.js `onHitIn`：
   * 整段物理/法术伤害被 `cancel`、扣 1 层、破盾时放 `shieldBreak`）：
   * 官方的莱茵生命防卫科高级成员（`enemy_1249_lysdb_2`，`Shield.max_block_damage_cnt`）与假想敌：再生的
   * 光环（`times.js kitRegen`，`Aura.max_damage_block_cnt`）用的都是它。卡名「莱茵护甲」也来自前者。
   *
   * **直到 2026-10-16 这里用的是 `hitCount` + `setHits`，那是个静默的错误**：`setHits` 会把 `base.maxHp`
   * 整个**覆盖**成"次数"（helpers.js 的注释就写着 `maxHp := hits`），于是每个敌人（十万血的首领也一样）
   * 变成 **3 点血**、血条直接消失 —— 业主报的「莱茵护甲怎么把怪的生命值改了」。`hitCount` 是给**器物 /
   * 频次怪**用的另一种机制（它们**本来就是**"打 N 次才倒"，没有血量可言），不是给"加一层盾"用的。
   *
   * 已经带着自己的次数盾的单位不再叠加（`Math.max`）：它自己那层还在，玩家打掉多少就是多少。
   */
  hitShield(battle, p) {
    const hits = Math.max(1, Math.round(pnum(p.hits, 3)));
    battle.on('enemySpawn', ({ enemy }) => {
      if (!enemy || !enemy.alive) return;
      const ab = abOf(battle, enemy);
      ab.hitShield = Math.max(ab.hitShield, hits);
    });
  },

  /**
   * 势不可挡: enemies demand one more block slot. `blockWeight` is the sim's own notion (blocking.js sums it against
   * an operator's `blockCnt`), so this is a +1 on the value the spawn already had — a 大力 enemy that needed 3 slots
   * now needs 4, which is the card's whole point.
   */
  blockDemand(battle, p) {
    const add = Math.max(1, Math.round(pnum(p.add, 1)));
    battle.on('enemySpawn', ({ enemy }) => {
      if (!enemy || !enemy.alive) return;
      if (isHitCount(enemy)) return;
      enemy.blockWeight = (enemy.blockWeight ?? 1) + add;
    });
  },

  /**
   * 食尸: when an enemy is knocked out, the enemies around the corpse are healed for a share of THAT ENEMY'S max HP.
   *
   * `reason === 'killed'` is the gate every death kit uses (archetypes.js `death`): `Battle._remove` fires `death`
   * for a leak and an expiry too, and a leak is not a corpse to feed on.
   */
  cannibalize(battle, p) {
    const pct = pnum(p.pct, 5) / 100;
    const radius = pnum(p.radius, 1);
    const shape = p.shape === 'box' ? 'box' : 'plus';
    battle.on('death', ({ unit, reason }) => {
      if (reason !== 'killed') return;
      if (!unit || unit.side !== 'enemy' || isHitCount(unit)) return;
      const amount = unit.s.maxHp * pct;
      if (!(amount > 0)) return;
      for (const e of battle.enemies) {
        if (!e || !e.alive || e === unit || isHitCount(e)) continue;
        const dr = Math.abs(e.tileR - unit.tileR);
        const dc = Math.abs(e.tileC - unit.tileC);
        const inside = shape === 'box' ? Math.max(dr, dc) <= radius : dr + dc <= radius;
        if (inside) battle.heal(e, e, amount);
      }
    });
  },

  /**
   * 静默: every `period` s ONE random own operator takes a large 凋亡损伤 (necrosis) tick.
   *
   * Necrosis is an ELEMENT gauge, not HP damage (damage.js `applyElement`), which is what a 损伤 means in this
   * engine — the operator's HP is untouched until the gauge bursts. `elem` is the enemy-side entry point for it.
   * Operators only: a token/trap is not an operator (the same narrowing 腐蚀领域 needed, §29.32).
   */
  silence(battle, p) {
    const period = pnum(p.period, 35);
    const amount = pnum(p.damage, 1000);
    battle.on('tick', () => {
      if (!(battle.time > 0)) return;
      if (battle.time + 1e-9 < (battle._hexSilenceNext ?? period)) return;
      battle._hexSilenceNext = battle.time + period;
      const ops = battle.allies().filter((u) => u && u.kind === 'op' && u.alive && u.deployed);
      if (!ops.length) return;
      const pick = ops[Math.min(ops.length - 1, Math.floor(battle.rng() * ops.length))];
      elem(battle, null, pick, 'necrosis', amount, { ignoreSelect: true, tags: ['hexVerb'] });
    });
  },

  /**
   * 重伤: an enemy's hit cuts the struck operator's 受治疗量 (healing received) for a few seconds.
   *
   * `healingTakenMul` is the stat the engine's heal path reads (units.js: `healingTakenMul` / `healingDealtMul`
   * are the two multipliers the heal pipe folds in); a timed buff is how every other debuff in this codebase lands
   * (addBuff + `duration`).
   */
  healCut(battle, p) {
    const pct = Math.max(0, Math.min(90, pnum(p.pct, 20))) / 100;
    const seconds = pnum(p.seconds, 4);
    battle.on('damaged', (c) => {
      const src = c && c.source;
      const tgt = c && c.target;
      if (!src || src.side !== 'enemy') return;
      if (!tgt || tgt.side !== 'ally' || tgt.kind !== 'op' || !tgt.alive) return;
      if (c.dmg && c.dmg.tags && c.dmg.tags.includes('hexVerb')) return;
      if (!(c.amount > 0)) return;
      battle.addBuff(tgt, {
        key: 'hexverb:healcut', duration: seconds, refresh: 'replace', visible: true, tags: ['hex'],
        mods: { healingTakenMul: 1 - pct },
      });
    });
  },

  /**
   * 自适应: every hit an enemy TAKES adds DEF, up to a cap.
   *
   * The stack is a persistent buff replaced each time (so a re-application cannot grow unbounded), and the cap is
   * read off the card's own `max` percentage — 30 % by the roster's numbers.
   */
  adaptive(battle, p) {
    const perHit = pnum(p.perHit, 2) / 100;
    const max = pnum(p.max, 30) / 100;
    const cur = new Map();
    battle.on('damaged', (c) => {
      const tgt = c && c.target;
      if (!tgt || tgt.side !== 'enemy' || !tgt.alive) return;
      if (isHitCount(tgt)) return;
      if (c.dmg && c.dmg.tags && c.dmg.tags.includes('hexVerb')) return;
      if (!(c.amount > 0)) return;
      const now = Math.min(max, (cur.get(tgt) || 0) + perHit);
      if (now <= (cur.get(tgt) || 0)) return;
      cur.set(tgt, now);
      passiveBuff(battle, tgt, 'hexverb:adaptive', { defPct: now });
    });
  },

  /**
   * 物转法: physical enemies deal ARTS instead of physical (usually at a reduced ATK — that trade is the roster's
   * own `mods`).
   *
   * This is a per-unit PROFILE change, not a hook: the sim asks `(e.profile && e.profile.dmgType) || def.dmgType` when
   * it fires (ai.js:867), so rewriting the profile on spawn is what makes every later swing arts — secondary hits
   * (splash, aftershock) included, which a per-attack hook would leave physical. Both carriers are written: the profile
   * is what the attack reads, and `def` is what a later form change re-derives it from.
   */
  transmute(battle, p) {
    battle.on('enemySpawn', ({ enemy }) => {
      if (!enemy || !enemy.alive) return;
      if (isHitCount(enemy)) return;
      const cur = (enemy.profile && enemy.profile.dmgType) || (enemy.def && enemy.def.dmgType);
      // 物理 only: an enemy that already deals arts is left as it is (the card is a CONVERSION, not an override).
      if (cur !== 'phys') return;
      // `def` IS FROZEN (simdata freezes every record it hands out), so a property write is a silent no-op in sloppy
      // mode and a TypeError in strict — the card would simply never fire. Replacing the object with a shallow copy
      // is the supported way to override one field. Both carriers are written: `profile.dmgType` is what the attack
      // reads (ai.js:867), and `def` is what a later form change re-derives the profile from.
      if (enemy.def) enemy.def = { ...enemy.def, dmgType: 'arts' };
      if (enemy.profile) enemy.profile = { ...enemy.profile, dmgType: 'arts' };
      enemy.markDirty();
    });
  },

  /**
   * 易碎铠甲: enemies open with more DEF and less speed, and every hit taken shaves DEF back down — down to (never
   * below) the pre-card value.
   *
   * '至多降低至原值' is the floor: the card's own opening bonus is what gets eaten, so a fully-shattered enemy is the
   * enemy the stage would have spawned anyway. The floor is captured ON SPAWN, before the bonus is applied, and kept
   * per unit — reading `def` live would let a later DEF buff raise the floor with it.
   */
  brittleArmor(battle, p) {
    const openPct = pnum(p.defPct, 50) / 100;
    const speedPct = Math.max(0, Math.min(90, pnum(p.speedPct, 20))) / 100;
    const shave = pnum(p.shavePct, 5) / 100;
    const floors = new WeakMap();
    const lost = new WeakMap();
    battle.on('enemySpawn', ({ enemy }) => {
      if (!enemy || !enemy.alive) return;
      if (isHitCount(enemy)) return;
      floors.set(enemy, enemy.s.def);
      lost.set(enemy, 0);
      passiveBuff(battle, enemy, 'hexverb:brittle:def', { defPct: openPct });
      // moveMul is the sim's own move-speed multiplier (units.js: moveSpeed = (base + ΣmoveFlat) × ΠmoveMul).
      passiveBuff(battle, enemy, 'hexverb:brittle:spd', { moveMul: 1 - speedPct });
    });
    battle.on('damaged', (c) => {
      const tgt = c && c.target;
      if (!tgt || tgt.side !== 'enemy' || !tgt.alive) return;
      if (isHitCount(tgt)) return;
      if (c.dmg && c.dmg.tags && c.dmg.tags.includes('hexVerb')) return;
      if (!(c.amount > 0)) return;
      const floor = floors.get(tgt);
      if (!Number.isFinite(floor) || floor <= 0) return;
      const cap = floor * openPct;
      const had = lost.get(tgt) || 0;
      if (had >= cap) return;
      const next = Math.min(cap, had + floor * shave);
      lost.set(tgt, next);
      passiveBuff(battle, tgt, 'hexverb:brittle:def', { defPct: openPct - next / floor });
    });
  },

  /**
   * 无头苍蝇: enemies move faster, but every `period` s they are 恐惧 (feared) for a couple of seconds.
   *
   * Bosses and hidden (隐匿) enemies are exempt — the roster's own text says so. A 器物 is not a body either.
   * The speed half is a plain passive; the fear half is a per-tick sweep, because the state is TIMED (the sim's
   * `applyStatus` owns the expiry and the 抵抗 roll).
   */
  restless(battle, p) {
    const period = pnum(p.period, 10);
    const seconds = pnum(p.seconds, 2);
    battle.on('tick', () => {
      if (!(battle.time > 0)) return;
      if (battle.time + 1e-9 < (battle._hexRestlessNext ?? period)) return;
      battle._hexRestlessNext = battle.time + period;
      for (const e of battle.enemies) {
        if (!e || !e.alive) continue;
        if (e.tag === 'boss' || e.isBoss) continue;
        if (e.s.flags.stealth) continue;
        if (isHitCount(e)) continue;
        battle.applyStatus(e, 'fear', { duration: seconds, source: null });
      }
    });
  },

  /** zzz: every `period` s ONE random own operator falls asleep for a couple of seconds. */
  drowse(battle, p) {
    const period = pnum(p.period, 20);
    const seconds = pnum(p.seconds, 2);
    battle.on('tick', () => {
      if (!(battle.time > 0)) return;
      if (battle.time + 1e-9 < (battle._hexDrowseNext ?? period)) return;
      battle._hexDrowseNext = battle.time + period;
      const ops = battle.allies().filter((u) => u && u.kind === 'op' && u.alive && u.deployed);
      if (!ops.length) return;
      const pick = ops[Math.min(ops.length - 1, Math.floor(battle.rng() * ops.length))];
      battle.applyStatus(pick, 'sleep', { duration: seconds, source: null });
    });
  },

  /**
   * 源石附身: every enemy carries the 活性原石 (active originium) effect — +ATK, +ASPD and a true-damage tick every
   * second, for `duration` s.
   *
   * The engine already models this exact effect (devices.js 'active originium': damage / atk / aspd / duration, PRTS
   * '部署于其上的我军和经过的敌军在{duration}s内…'). Here it is applied to the ENEMY SPAWN rather than to a tile, which
   * is the card's whole shape. The per-second tick is an authored true-damage instance: the roster's own text hides
   * the bracketed numbers from the player, so the tuning lives in `params`.
   */
  /**
   * 增益无效 (业主 2026-10-19): 「每隔20s干员属性增益无效3s」.
   *
   * "属性增益" = the buffs that carry STAT modifiers (atk / def / hp / aspd / res …): a buff counts when its `mods`
   * object has at least one key. Pure flag buffs (a shield's marker, 无敌, a status carrier) are left alone — the card
   * says 属性增益, and stripping a shield or 无敌 would be a different (and much stronger) effect.
   *
   * HOW: every `period` seconds, for `seconds` seconds, every OWN operator's qualifying buffs are removed and put back
   * afterwards. Removing + restoring (rather than a "muted" flag the aggregation would have to learn) is the same
   * shape 幽魂形态's cap uses for a per-instance rule; the buffs are captured with their remaining time so a
   * 3 s mute does not silently refresh a 10 s buff. A buff that ran out DURING the mute is not restored (its timeLeft
   * reached 0 and its own expiry is the engine's business). [ASSUMED: 1) 「干员」 = the ALLY operators, not the enemies;
   * 2) stat buffs only (a buff whose `mods` is null is not an 属性增益); 3) the mute is re-applied every period, and the
   * first one lands one period in (not at battle start).]
   */
  buffVoid(battle, p) {
    const period = pnum(p.period, 20);
    const seconds = pnum(p.seconds, 3);
    const KEY = 'hexverb:buffvoid';
    let muted = false;
    const atStart = (fn) => { if (battle.started) fn(); else battle.on('battleStart', fn); };
    atStart(() => {
      battle.every(period, () => {
        if (muted) return;
        muted = true;
        const saved = [];
        for (const u of alliesOf(battle)) {
          if (!u || !u.alive || !u.deployed || u.kind !== 'op') continue;
          const strip = [];
          for (const b of [...(u.buffs || [])]) {
            if (!b || !b.mods || b.pack) continue;          // pack buffs are a plugin's budget: never touched
            if (b.key === KEY) continue;
            strip.push(b);
          }
          for (const b of strip) {
            saved.push({ u, b: { ...b, mods: b.mods, flags: b.flags }, timeLeft: b.timeLeft });
            battle.removeBuff(u, b.key);
          }
        }
        battle.after(seconds, () => {
          muted = false;
          for (const { u, b, timeLeft } of saved) {
            if (!u || !u.alive || !u.deployed) continue;
            if (!(timeLeft > 0)) continue;
            battle.addBuff(u, { ...b, duration: timeLeft, timeLeft, refresh: 'replace', allowDead: false });
          }
        });
      }, { immediate: false });
    });
  },

  /**
   * 窃贼 (业主 2026-10-19): 「干员被击倒时下回合减少2%金钱（最多30%）」.
   *
   * The battle half only COUNTS: every own operator knocked out during this battle is tallied onto the battle's own
   * `battle._hexThiefDeaths`. The match reads it when the battle's result is released and charges the penalty on the
   * NEXT round's income (server/match/hextech.js `applyThiefPenalty`, an `onIncome` handler) — income is match state,
   * and the sim has no business touching it. Keeping the count on the battle (not on the match) means a re-simulation of
   * the same field recounts the same number and the two paths cannot drift.
   *
   * `reason === 'killed'` is the same gate 亡语 uses: a leak / an expiry / a retreat is not 被击倒. [ASSUMED: 1) only
   * the owners' operators count in a 联防 field (the card is the enemy side's, so every player it fights is a target —
   * this counts EVERY ally operator, which is what the card's wording means on a shared field); 2) the percentage is
   * applied to the next round's income only (it does not compound across rounds unless more are knocked out); 3) the cap
   * is read from the roster's `params.capPct` (30).]
   */
  thief(battle, p) {
    const perDeathPct = Number.isFinite(Number(p.perDeathPct)) ? Number(p.perDeathPct) : 2;
    battle._hexThiefDeaths = 0;
    battle._hexThiefPct = perDeathPct;
    battle.on('death', ({ unit, reason }) => {
      if (reason !== 'killed') return;
      if (!unit || unit.side !== 'ally' || unit.kind !== 'op') return;
      battle._hexThiefDeaths += 1;
    });
  },

  /**
   * 流星 (业主 2026-10-19): 「敌人获得30%物理闪避」.
   *
   * Every spawned enemy gets a persistent `dodgePhys` buff (`p.chance`, 0.3 by default). The engine already rolls
   * `dodgePhys` for physical hits on ANY unit (damage.js dealDamage), which is why the official 流星-style kits read
   * the same mod. [ASSUMED: 1) it is a buff, so a boss is covered too (the card names no exception); 2) arts / true
   * damage is unaffected — 物理闪避 is physical only; 3) it stacks with an enemy's own dodge roll as the engine's
   * independent-source rule does (aggregateMods).]
   */
  physDodge(battle, p) {
    const chance = Math.max(0, Math.min(1, Number.isFinite(Number(p.chance)) ? Number(p.chance) : 0.3));
    if (!(chance > 0)) return;
    const KEY = 'hexverb:physdodge';
    const apply = (e) => {
      if (!e || !e.alive || e.side !== 'enemy' || e.findBuff(KEY)) return;
      battle.addBuff(e, { key: KEY, duration: Infinity, persist: true, mods: { dodgePhys: chance }, tags: ['hexVerb'] });
    };
    for (const e of battle.enemies) apply(e);
    battle.on('enemySpawn', ({ enemy }) => apply(enemy));
  },

  /**
   * 通缉令 (业主 2026-10-19): 「每场战斗随机增加一个1~5块（惊变里的）的敌人」.
   *
   * 「惊变里的 1~5 块」 = the bounty cards of the 机变 draft, which carry a `coin` price of 1–5 (data/choices.json
   * `cards`: 42 at 1, 40 at 2, 36 at 3, 5 at 4, 4 at 5). The card adds ONE such enemy to every battle.
   *
   * The choice has to be made by the MATCH (it owns choices.json and the seeded RNG), so the id arrives on the battle's
   * flags as `flags.enemyHexWanted` (one enemyKey); this script only spawns it. A battle without the flag (a harness,
   * a re-computation that did not get it) simply spawns nothing — never a random pick here, because a battle-local
   * `Math.random` would break determinism (the rule server/sim lives by).
   *
   * 业主 2026-10-20「联防时敌方协议悬赏令的怪路径有问题」: this used to spawn on `routeIndex: 0` unconditionally. A 联防
   * field carries the routes of **every** leaked wave, and the first one is routinely a FLY lane — so a ground monster
   * was handed a flyer's straight-line path and walked over cliffs and rocks (measured: 482 ticks on non-walkable
   * tiles, while a WALK unit on a WALK route had 0). A route is now chosen to match the spawn's own motion: a flyer
   * prefers a FLY lane, a walker takes a non-FLY one. No route of the right kind ⇒ index 0 as before (nothing better
   * exists; the engine never pathfinds route polylines, it just walks them).
   */
  wanted(battle) {
    const key = battle.flags && typeof battle.flags.enemyHexWanted === 'string' ? battle.flags.enemyHexWanted : '';
    if (!key) return;
    const atStart = (fn) => { if (battle.started) fn(); else battle.on('battleStart', fn); };
    atStart(() => {
      battle.spawnEnemy(key, { routeIndex: routeIndexForMotion(battle, key) });
    });
  },

  /**
   * 通厕大队 (业主 2026-10-19): 「战斗增加3个杰斯顿属性为原来的（2+6x%，x为回合数）」.
   *
   * Three 杰斯顿·威廉姆斯 (`enemy_1516_jakill`, the boss-tagged 狱警) added at battle start. "属性为原来的 2 + 6x%" is
   * read as a PERCENTAGE of the original stats: (2 + 6x)%, so R1 → 8 %, R5 → 32 %, R14 → 86 %. x is the round being
   * fought (`battle.round`, the same reading 腐蚀领域 and 回响 use).
   *
   * The scaling rides `spawnEnemy`'s inline `def` (it normalises a plain data-shaped record), so the official
   * record is untouched. The three land on route 0 at its start. [ASSUMED: 1) 「2+6x%」 is a percent, not "2 + 6x
   * times" — a literal ×2 at R1 would already be a boss-grade wall in the first round; 2) HP/ATK/DEF/RES scale, move
   * speed and attack interval do not (they are not 「属性」 in the sense that would make the card stronger); 3) the
   * three are ordinary spawns: they can leak, be blocked and count toward the enemy total like any wave enemy.]
   */
  jekyllSquad(battle, p) {
    const count = Math.max(1, Math.min(20, Math.trunc(pnum(p.count, 3))));
    const key = typeof p.enemyKey === 'string' && p.enemyKey ? p.enemyKey : 'enemy_1516_jakill';
    const basePct = Number.isFinite(Number(p.basePct)) ? Number(p.basePct) : 2;
    const perRoundPct = Number.isFinite(Number(p.perRoundPct)) ? Number(p.perRoundPct) : 6;
    // content is installed AFTER `start()` emitted battleStart (server/sim/Battle.js), so a verb that must act at battle
    // start runs NOW when the battle has already started, and on the event otherwise (a harness, a future re-order).
    const atStart = (fn) => { if (battle.started) fn(); else battle.on('battleStart', fn); };
    atStart(() => {
      const round = Number.isFinite(Number(battle.round)) && Number(battle.round) > 0 ? Number(battle.round) : 1;
      const pct = Math.max(1, basePct + perRoundPct * round) / 100;
      // the battle's own data source (server/sim/Battle.js `this.data`): getEnemy is the accessor every content reader uses
      const rec = battle.data && typeof battle.data.getEnemy === 'function' ? battle.data.getEnemy(key) : null;
      if (!rec) return;   // no record (a stripped data set): nothing to scale, nothing to spawn
      // `rec` is ALREADY normalised (simdata.js normalizeEnemy), so the inline record is built in the FLAT shape
      // normalizeEnemy reads (`st = e.stats ?? e`) — keep every field, scale the four stat axes, publish them flat.
      // `rec` is the NORMALISED record (simdata.js normalizeEnemy), and spawnEnemy takes an ALREADY-normalised record
      // as-is when it sees one (`opts.def.immune instanceof Set`) — so the scaled fields go on the record ITSELF, not in
      // a nested `stats` object, or the copy would be treated as final and the scaling silently ignored.
      const n = (v, d) => (typeof v === 'number' && Number.isFinite(v) ? Math.max(0, v) : d);
      const def = {
        ...rec,
        maxHp: Math.max(1, n(rec.maxHp, 1) * pct),
        atk: n(rec.atk, 0) * pct,
        def: n(rec.def, 0) * pct,
        res: n(rec.res, 0) * pct,
      };
      const route = battle._routeFor(0);
      const start = route && Array.isArray(route.start) ? route.start : [battle.rect.r0, battle.rect.c1];
      for (let i = 0; i < count; i++) {
        battle.spawnEnemy(key, { pos: [start[0], start[1] + i * 0.2], routeIndex: 0, def });
      }
    });
  },

  originium(battle, p) {
    const duration = pnum(p.duration, 200);
    const atkPct = pnum(p.atkPct, 50) / 100;
    const aspd = pnum(p.aspd, 40);
    const dps = pnum(p.dps, 40);
    battle.on('enemySpawn', ({ enemy }) => {
      if (!enemy || !enemy.alive) return;
      if (isHitCount(enemy)) return;
      battle.addBuff(enemy, {
        key: 'hexverb:originium', duration, refresh: 'replace', visible: true, tags: ['hex'],
        mods: { atkPct, aspd },
        interval: 1,
        onTick: ({ battle: b, unit: u }) => {
          if (!u || !u.alive) return;
          b.dealDamage(null, u, { amount: dps, type: 'true', canDodge: false, sourceless: true, tags: ['hexVerb', 'originium'] });
        },
      });
    });
  },
});
